      AppLesson(
        title: "Ripples",
        body: "title: Add Material touch ripples\ndescription: How to implement ripple animations.\n\nWidgets that follow the Material Design guidelines display\na ripple animation when tapped.\n\nFlutter provides the [InkWell][]\nwidget to perform this effect.\nCreate a ripple effect using the following steps:\nCreate a widget that supports tap.\nWrap it in an InkWell widget to manage tap callbacks and\n     ripple animations.\n\nInteractive example\n\ndartpad title=\"Flutter Material ripples hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'InkWell Demo';\n\n    return const MaterialApp(\n      title: title,\n      home: MyHomePage(title: title),\n    );\n  }\n}\n\nclass MyHomePage extends StatelessWidget {\n  final String title;\n\n  const MyHomePage({super.key, required this.title});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: Text(title)),\n      body: const Center(child: MyButton()),\n    );\n  }\n}\n\nclass MyButton extends StatelessWidget {\n  const MyButton({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    // The InkWell wraps the custom flat button widget.\n    return InkWell(\n      // When the user taps the button, show a snackbar.\n      onTap: () {\n        ScaffoldMessenger.of(\n          context,\n        ).showSnackBar(const SnackBar(content: Text('Tap')));\n      },\n      child: const Padding(\n        padding: EdgeInsets.all(12),\n        child: Text('Flat Button'),\n      ),\n    );\n  }\n}",
        codeSnippet: "// The InkWell wraps the custom flat button widget.\nInkWell(\n  // When the user taps the button, show a snackbar.\n  onTap: () {\n    ScaffoldMessenger.of(\n      context,\n    ).showSnackBar(const SnackBar(content: Text('Tap')));\n  },\n  child: const Padding(\n    padding: EdgeInsets.all(12),\n    child: Text('Flat Button'),\n  ),\n)",
        hasImage: false,
      ),
      AppLesson(
        title: "Fading In Images",
        body: "title: Fade in images with a placeholder\ndescription: How to fade images into view.\n\nWhen displaying images using the default Image widget,\nyou might notice they simply pop onto the screen as they're loaded.\nThis might feel visually jarring to your users.\n\nInstead, wouldn't it be nice to display a placeholder at first,\nand images would fade in as they're loaded? Use the\n[FadeInImage][] widget for exactly this purpose.\n\nFadeInImage works with images of any type: in-memory, local assets,\nor images from the internet.\nIn-memory\n\nTo use a single-pixel, transparent PNG as the placeholder image,\ncomplete the following steps:\nCreate the transparent image data.\n\n    Import dart:convert and dart:typed_data,\n    then decode the image from a Base64-encoded string:\n\n\nUse the image data as a placeholder.\n\n    Pass the decoded image data to the placeholder parameter:\n\n\n\n\n{:.steps}\nComplete example\n\n{:.site-mobile-screenshot}\nFrom asset bundle\n\nTo use a local image asset as the placeholder image,\ncomplete the following steps:\nAdd the placeholder to the asset bundle.\n\n    Add a placeholder image to the project's assets directory,\n    such as assets/loading.gif.\n    Then, declare the asset in the project's pubspec.yaml file.\n    For more details, see [Adding assets and images][].\n\n    yaml diff\n      flutter:\n        assets:\n- assets/loading.gif\n    dart\n    FadeInImage.assetNetwork(\n      placeholder: 'assets/loading.gif',\n      image: 'https://picsum.photos/250?image=9',\n    ),\n    dart\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(const MyApp());\n}\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Fade in images';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: Center(\n          child: FadeInImage.assetNetwork(\n            placeholder: 'assets/loading.gif',\n            image: 'https://picsum.photos/250?image=9',\n          ),\n        ),\n      ),\n    );\n  }\n}\n\n{:.site-mobile-screenshot}",
        codeSnippet: "import 'dart:convert';\n    import 'dart:typed_data';\n    final Uint8List transparentImage = base64Decode(\n      'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4'\n      'nGMAAQAABQABDQottAAAAABJRU5ErkJggg==',\n    );\n    \n\n    FadeInImage.memoryNetwork(\n      placeholder: transparentImage,\n      image: 'https://picsum.photos/250?image=9',\n    ),\n    \n\nimport 'dart:convert';\nimport 'dart:typed_data';\n\nimport 'package:flutter/material.dart';\n\nfinal Uint8List transparentImage = base64Decode(\n  'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAACklEQVR4'\n  'nGMAAQAABQABDQottAAAAABJRU5ErkJggg==',\n);\n\nvoid main() {\n  runApp(const MyApp());\n}\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Fade in images';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: Stack(\n          children: <Widget>[\n            const Center(child: CircularProgressIndicator()),\n            Center(\n              child: FadeInImage.memoryNetwork(\n                placeholder: transparentImage,\n                image: 'https://picsum.photos/250?image=9',\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\n1.  **Use the asset as a placeholder.**\n\n    Pass the asset path to the `placeholder` parameter of\n    the [`FadeInImage.assetNetwork`][] constructor:\n\n    <?code-excerpt \"lib/asset_main.dart (AssetNetwork)\" replace=\"/^child\\: //g\"?>\n    \n\n{:.steps}\n\n### Complete example\n\n<?code-excerpt \"lib/asset_main.dart\"?>",
        hasImage: true,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter images cookbook\nshortTitle: Images\ndescription: A catalog of recipes for handling images in your Flutter app.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Network Image",
        body: "title: Display images from the internet\ndescription: How to display images from the internet.\n\nDisplaying images is fundamental for most mobile apps.\nFlutter provides the [Image][] widget to\ndisplay different types of images.\n\nTo work with images from a URL, use the\n[Image.network()][] constructor.\n\nBonus: animated gifs\n\nOne useful thing about the Image widget:\nIt supports animated gifs.\n\nImage fade in with placeholders\n\nThe default Image.network constructor doesn't handle more advanced\nfunctionality, such as fading images in after loading.\nTo accomplish this task,\ncheck out [Fade in images with a placeholder][].\n[Fade in images with a placeholder][]\nInteractive example\n\ndartpad title=\"Flutter network images hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    var title = 'Web Images';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: Text(title)),\n        body: Image.network('https://picsum.photos/250?image=9'),\n      ),\n    );\n  }\n}",
        codeSnippet: "Image.network('https://picsum.photos/250?image=9'),\n\nImage.network(\n  'https://docs.flutter.dev/assets/images/dash/dash-fainting.gif',\n);",
        hasImage: false,
      ),
      AppLesson(
        title: "This is a placeholder page (Firebase redirects this page's URL to another);",
        body: "title: Cookbook\ndescription: >-\n  The Flutter cookbook provides recipes for many commonly performed tasks.\nsitemap: false\nit is necessary to allow breadcrumbs to work.\n\nThis cookbook contains recipes that demonstrate how to\nsolve common problems while writing Flutter apps.\nEach recipe is self-contained and can be used as a reference to\nhelp you build up an application with Flutter.\n\nTo discover recipes and other learning materials relevant to you,\ncheck out the [learning resources index][].",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Basic List",
        body: "title: Use lists\ndescription: How to implement a list.\n\nDisplaying lists of data is a fundamental pattern for mobile apps.\nFlutter includes the [ListView][]\nwidget to make working with lists a breeze.\nCreate a ListView\n\nUsing the standard ListView constructor is\nperfect for lists that contain only a few items.\nThe built-in [ListTile][]\nwidget is a way to give items a visual structure.\n\nInteractive example\n\ndartpad title=\"Flutter lists hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Basic List';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: ListView(\n          children: const [\n            ListTile(leading: Icon(Icons.map), title: Text('Map')),\n            ListTile(leading: Icon(Icons.photo_album), title: Text('Album')),\n            ListTile(leading: Icon(Icons.phone), title: Text('Phone')),\n          ],\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "ListView(\n  children: const <Widget>[\n    ListTile(leading: Icon(Icons.map), title: Text('Map')),\n    ListTile(leading: Icon(Icons.photo_album), title: Text('Album')),\n    ListTile(leading: Icon(Icons.phone), title: Text('Phone')),\n  ],\n),",
        hasImage: false,
      ),
      AppLesson(
        title: "Floating App Bar",
        body: "title: Place a floating app bar above a list\ndescription: How to place a floating app bar or navigation bar above a list.\n\nThis guide describes how to place a floating app bar or\nnavigation bar above a list in a Flutter app.\nOverview\n\nTo make it easier for users to view a list of items,\nyou might want to minimize the app bar (navigation bar), as\nthe user scrolls down the list.\n\nMoving the app bar into a [CustomScrollView][] allows you\nto create an app bar that can be minimized or scroll\noffscreen as you scroll through a list of items contained\ninside the CustomScrollView.\n\nThis recipe demonstrates how to use a CustomScrollView to\ndisplay a list of items with an app bar on top that\nminimizes as the user scrolls down the list using the\nfollowing steps:\nCreate a CustomScrollView.\nAdd a floating app bar to CustomScrollView.\nAdd a list of items to CustomScrollView.\nCreate a CustomScrollView\n\nTo create a floating app bar, place the app bar inside a\nCustomScrollView that also contains the list of items.\nThis synchronizes the scroll position of the app bar and the\nlist of items. You might think of the CustomScrollView\nwidget as a ListView that allows you to mix and match\ndifferent types of scrollable lists and widgets together.\n\nThe scrollable lists and widgets provided to the\nCustomScrollView are known as slivers. There are several\ntypes of slivers, such as SliverList, SliverGrid, and\nSliverAppBar. In fact, the ListView and GridView\nwidgets use the SliverList and SliverGrid widgets to\nimplement scrolling.\n\nFor this example, create a CustomScrollView that contains\na SliverList. Also, remove the app bar property from your\ncode if it exists.\n\nAdd a floating app bar\n\nNext, add an app bar to the [CustomScrollView][].\n\nFlutter provides the [SliverAppBar][] widget which,\nmuch like the normal AppBar widget,\nuses the SliverAppBar to display a title,\ntabs, images and more.\n\nHowever, the SliverAppBar also gives you the ability to\ncreate a \"floating\" app bar that shrinks and floats when\nyou're not at the top of the page.\n\nTo create this effect:\nStart with an app bar that displays only a title.\nSet the pinned property to true.\nAdd a flexibleSpace widget that fills the available\n     expandedHeight.\n\n:::tip\nPlay around with the\n[various properties you can pass to the SliverAppBar widget][],\nand use hot reload to see the results. For example, use an\nImage widget for the flexibleSpace property to create a\nbackground image that shrinks in size as it's scrolled offscreen.\n:::\n\nFlutter provides the [CupertinoSliverNavigationBar][]\nwidget, which lets you have a \"floating\" navigation\nbar that shrinks when you scroll down and floats when\nyou're not at the top of the page.\n\nTo create this effect:\nAdd CupertinoSliverNavigationBar to\n     CustomScrollView.\nStart with an app bar that displays only a title.\n\nAdd a list of items\n\nNow that you have the app bar in place, add a list of items\nto the CustomScrollView. You have two options: a\n[SliverList][] or a [SliverGrid][].  If you need to\ndisplay a list of items one after the other, use the\nSliverList widget. If you need to display a grid list, use\nthe SliverGrid widget.\n\nInteractive example\n\ndartpad title=\"Flutter floating app bar hands-on example in DartPad\" run=\"false\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Floating App Bar';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        // No app bar provided to Scaffold, only a body with a\n        // CustomScrollView.\n        body: CustomScrollView(\n          slivers: [\n            // Add the app bar to the CustomScrollView.\n            const SliverAppBar(\n              // Provide a standard title.\n              title: Text(title),\n              // Pin the app bar when scrolling\n              pinned: true,\n              // Display a placeholder widget to visualize the shrinking size.\n              flexibleSpace: Placeholder(),\n              // Make the initial height of the SliverAppBar larger than normal.\n              expandedHeight: 200,\n            ),\n            // Next, create a SliverList\n            SliverList.builder(\n              // The builder function returns a ListTile with a title that\n              // displays the index of the current item.\n              itemBuilder: (context, index) =>\n                  ListTile(title: Text('Item #\$index')),\n              // Builds 50 ListTiles\n              itemCount: 50,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\ndartpad title=\"Flutter floating navigation bar hands-on example in DartPad\" run=\"false\"\nimport 'package:flutter/cupertino.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Floating Navigation Bar';\n\n    return CupertinoApp(\n      title: title,\n      home: CupertinoPageScaffold(\n        // No navigation bar provided to CupertinoPageScaffold,\n        // only a body with a CustomScrollView.\n        child: CustomScrollView(\n          slivers: [\n            // Add the navigation bar to the CustomScrollView.\n            const CupertinoSliverNavigationBar(\n              // Provide a standard title.\n              largeTitle: Text(title),\n            ),\n            // Next, create a SliverList\n            SliverList.builder(\n              // The builder function returns a CupertinoListTile with a title\n              // that displays the index of the current item.\n              itemBuilder: (context, index) =>\n                  CupertinoListTile(title: Text('Item #\$index')),\n              // Builds 50 CupertinoListTile\n              itemCount: 50,\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "MaterialApp(\n  title: 'Floating App Bar',\n  home: Scaffold(\n    // No app bar property provided yet.\n    body: CustomScrollView(\n      // Add the app bar and list of items as slivers in the next steps.\n      slivers: <Widget>[],\n    ),\n  ),\n);\n\nCupertinoApp(\n  title: 'Floating Navigation Bar',\n  home: CupertinoPageScaffold(\n    // No navigation bar property provided yet.\n    child: CustomScrollView(\n      // Add the navigation bar and list of items as slivers in the next steps.\n      slivers: <Widget>[],\n    ),\n  ),\n);\n\nslivers: [\n  // Add the app bar to the CustomScrollView.\n  SliverAppBar(\n    // Provide a standard title.\n    title: Text('Floating App Bar'),\n    // Pin the app bar when scrolling.\n    pinned: true,\n    // Display a placeholder widget to visualize the shrinking size.\n    flexibleSpace: Placeholder(),\n    // Make the initial height of the SliverAppBar larger than normal.\n    expandedHeight: 200,\n  ),\n],\n\nslivers: [\n  // Add the navigation bar to the CustomScrollView.\n  CupertinoSliverNavigationBar(\n    // Provide a standard title.\n    largeTitle: Text('Floating App Bar'),\n  ),\n],\n\n// Next, create a SliverList\nSliverList.builder(\n  // The builder function returns a ListTile with a title that\n  // displays the index of the current item.\n  itemBuilder: (context, index) =>\n      ListTile(title: Text('Item #\$index')),\n  // Builds 50 ListTiles\n  itemCount: 50,\n)\n\n// Next, create a SliverList\nSliverList.builder(\n  // The builder function returns a CupertinoListTile with a title\n  // that displays the index of the current item.\n  itemBuilder: (context, index) =>\n      CupertinoListTile(title: Text('Item #\$index')),\n  // Builds 50 CupertinoListTile\n  itemCount: 50,\n)\n\n<noscript>\n  <img src=\"/assets/images/docs/cookbook/floating-app-bar.webp\" alt=\"Use floating app bar demo\" class=\"site-mobile-screenshot\"/>\n</noscript>\n\n</Tab>\n\n<Tab name=\"Cupertino widgets\">\n\n<?code-excerpt \"lib/main_cupertino.dart\"?>",
        hasImage: false,
      ),
      AppLesson(
        title: "Grid Lists",
        body: "title: Create a grid list\ndescription: How to implement a grid list.\n\nIn some cases, you might want to display your items as a grid rather than\na normal list of items that come one after the next.\nFor this task, use the [GridView][] widget.\n\nThe simplest way to get started using grids is by using the\n[GridView.count()][] constructor,\nbecause it allows you to specify how many rows or columns you'd like.\n\nTo visualize how GridView works,\ngenerate a list of 100 widgets that display their index in the list.\n\nInteractive example\n\ndartpad title=\"Flutter GridView hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(const MyApp());\n}\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Grid List';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: GridView.count(\n          // Create a grid with 2 columns.\n          // If you change the scrollDirection to horizontal,\n          // this produces 2 rows.\n          crossAxisCount: 2,\n          // Generate 100 widgets that display their index in the list.\n          children: List.generate(100, (index) {\n            return Center(\n              child: Text(\n                'Item \$index',\n                style: TextTheme.of(context).headlineSmall,\n              ),\n            );\n          }),\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "GridView.count(\n  // Create a grid with 2 columns.\n  // If you change the scrollDirection to horizontal,\n  // this produces 2 rows.\n  crossAxisCount: 2,\n  // Generate 100 widgets that display their index in the list.\n  children: List.generate(100, (index) {\n    return Center(\n      child: Text(\n        'Item \$index',\n        style: TextTheme.of(context).headlineSmall,\n      ),\n    );\n  }),\n),",
        hasImage: false,
      ),
      AppLesson(
        title: "Horizontal List",
        body: "title: Create a horizontal list\ndescription: How to implement a horizontal list.\n\nYou might want to create a list that scrolls\nhorizontally rather than vertically.\nThe [ListView][] widget supports horizontal lists.\n\nUse the standard ListView constructor, passing in a horizontal\nscrollDirection, which overrides the default vertical direction.\n\ndart highlightLines=2\nListView(\n  scrollDirection: Axis.horizontal,\n  children: [\n    for (final color in Colors.primaries)\n      Container(width: 160, color: color),\n  ],\n),\ndartpad title=\"Flutter horizontal list hands-on example in DartPad\" run=\"true\"\nimport 'dart:ui';\n\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Horizontal list';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: Container(\n          margin: const EdgeInsets.symmetric(vertical: 20),\n          height: 200,\n          child: ScrollConfiguration(\n            // Add a custom scroll behavior that\n            // allows all devices to drag the list.\n            behavior: const MaterialScrollBehavior().copyWith(\n              dragDevices: {...PointerDeviceKind.values},\n            ),\n            child: ListView(\n              scrollDirection: Axis.horizontal,\n              children: [\n                for (final color in Colors.primaries)\n                  Container(width: 160, color: color),\n              ],\n            ),\n          ),\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "[`ListView`]: {{site.api}}/flutter/widgets/ListView-class.html\n\n## Interactive example\n\n<?code-excerpt \"lib/main.dart\"?>",
        hasImage: false,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter lists cookbook\nshortTitle: Lists\ndescription: A catalog of recipes for handling lists in your Flutter app.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Long Lists",
        body: "title: Work with long lists\ndescription: Use ListView.builder to implement a long or infinite list.\n\nThe standard [ListView][] constructor works well\nfor small lists. To work with lists that contain\na large number of items, it's best to use the\n[ListView.builder][] constructor.\n\nIn contrast to the default ListView constructor, which requires\ncreating all items at once, the ListView.builder() constructor\ncreates items as they're scrolled onto the screen.\nCreate a data source\n\nFirst, you need a data source. For example, your data source\nmight be a list of messages, search results, or products in a store.\nMost of the time, this data comes from the internet or a database.\n\nFor this example, generate a list of 10,000 Strings using the\n[List.generate][] constructor.\n\nConvert the data source into widgets\n\nTo display the list of strings, render each String as a widget\nusing ListView.builder().\nIn this example, display each String on its own line.\n\nInteractive example\n\ndartpad title=\"Flutter create long list hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(\n    MyApp(\n      items: List.generate(10000, (i) => 'Item \$i'),\n    ),\n  );\n}\n\nclass MyApp extends StatelessWidget {\n  final List items;\n\n  const MyApp({super.key, required this.items});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Long List';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: ListView.builder(\n          itemCount: items.length,\n          prototypeItem: ListTile(title: Text(items.first)),\n          itemBuilder: (context, index) {\n            return ListTile(title: Text(items[index]));\n          },\n        ),\n      ),\n    );\n  }\n}\nChildren's extent\n\nTo specify each item's extent, you can use either [prototypeItem][], [itemExtent][],\nor [itemExtentBuilder][].\n\nSpecifying either is more efficient than letting the children determine their own extent\nbecause the scrolling machinery can make use of the foreknowledge of the children's\nextent to save work, for example when the scroll position changes drastically.\n\nUse [prototypeItem][] or [itemExtent][] if your list has items of fixed size.\n\nUse [itemExtentBuilder][] if your list has items of different sizes.",
        codeSnippet: "List<String>.generate(10000, (i) => 'Item \$i'),\n\nListView.builder(\n  itemCount: items.length,\n  prototypeItem: ListTile(title: Text(items.first)),\n  itemBuilder: (context, index) {\n    return ListTile(title: Text(items[index]));\n  },\n)",
        hasImage: false,
      ),
      AppLesson(
        title: "Mixed List",
        body: "title: Create lists with different types of items\ndescription: How to implement a list that contains different types of assets.\n\nYou might need to create lists that display different types of content.\nFor example, you might be working on a list that shows a heading\nfollowed by a few items related to the heading, followed by another heading,\nand so on.\n\nHere's how you can create such a structure with Flutter:\nCreate a data source with different types of items.\nConvert the data source into a list of widgets.\nCreate a data source with different types of items\nTypes of items\n\nTo represent different types of items in a list, define\na class for each type of item.\n\nIn this example, create an app that shows a header followed by five\nmessages. Therefore, create three classes: ListItem, HeadingItem,\nand MessageItem.\n\nCreate a list of items\n\nMost of the time, you would fetch data from the internet or a local\ndatabase and convert that data into a list of items.\n\nFor this example, generate a list of items to work with. The list\ncontains a header followed by five messages. Each message has one\nof 3 types: ListItem, HeadingItem, or MessageItem.\n\nConvert the data source into a list of widgets\n\nTo convert each item into a widget,\nuse the [ListView.builder()][] constructor.\n\nIn general, provide a builder function that checks for what type\nof item you're dealing with, and returns the appropriate widget\nfor that type of item.\n\nInteractive example\n\ndartpad title=\"Flutter create mixed lists hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(\n    MyApp(\n      items: List.generate(\n        1000,\n        (i) => i % 6 == 0\n            ? HeadingItem('Heading \$i')\n            : MessageItem('Sender \$i', 'Message body \$i'),\n      ),\n    ),\n  );\n}\n\nclass MyApp extends StatelessWidget {\n  final List items;\n\n  const MyApp({super.key, required this.items});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'Mixed List';\n\n    return MaterialApp(\n      title: title,\n      home: Scaffold(\n        appBar: AppBar(title: const Text(title)),\n        body: ListView.builder(\n          // Let the ListView know how many items it needs to build.\n          itemCount: items.length,\n          // Provide a builder function. This is where the magic happens.\n          // Convert each item into a widget based on the type of item it is.\n          itemBuilder: (context, index) {\n            final item = items[index];\n\n            return ListTile(\n              title: item.buildTitle(context),\n              subtitle: item.buildSubtitle(context),\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\n/// The base class for the different types of items the list can contain.\nabstract class ListItem {\n  /// The title line to show in a list item.\n  Widget buildTitle(BuildContext context);\n\n  /// The subtitle line, if any, to show in a list item.\n  Widget buildSubtitle(BuildContext context);\n}\n\n/// A ListItem that contains data to display a heading.\nclass HeadingItem implements ListItem {\n  final String heading;\n\n  HeadingItem(this.heading);\n\n  @override\n  Widget buildTitle(BuildContext context) {\n    return Text(heading, style: Theme.of(context).textTheme.headlineSmall);\n  }\n\n  @override\n  Widget buildSubtitle(BuildContext context) => const SizedBox.shrink();\n}\n\n/// A ListItem that contains data to display a message.\nclass MessageItem implements ListItem {\n  final String sender;\n  final String body;\n\n  MessageItem(this.sender, this.body);\n\n  @override\n  Widget buildTitle(BuildContext context) => Text(sender);\n\n  @override\n  Widget buildSubtitle(BuildContext context) => Text(body);\n}",
        codeSnippet: "/// The base class for the different types of items the list can contain.\nabstract class ListItem {\n  /// The title line to show in a list item.\n  Widget buildTitle(BuildContext context);\n\n  /// The subtitle line, if any, to show in a list item.\n  Widget buildSubtitle(BuildContext context);\n}\n\n/// A ListItem that contains data to display a heading.\nclass HeadingItem implements ListItem {\n  final String heading;\n\n  HeadingItem(this.heading);\n\n  @override\n  Widget buildTitle(BuildContext context) {\n    return Text(heading, style: Theme.of(context).textTheme.headlineSmall);\n  }\n\n  @override\n  Widget buildSubtitle(BuildContext context) => const SizedBox.shrink();\n}\n\n/// A ListItem that contains data to display a message.\nclass MessageItem implements ListItem {\n  final String sender;\n  final String body;\n\n  MessageItem(this.sender, this.body);\n\n  @override\n  Widget buildTitle(BuildContext context) => Text(sender);\n\n  @override\n  Widget buildSubtitle(BuildContext context) => Text(body);\n}\n\nfinal items = List<ListItem>.generate(\n  1000,\n  (i) => i % 6 == 0\n      ? HeadingItem('Heading \$i')\n      : MessageItem('Sender \$i', 'Message body \$i'),\n);\n\nListView.builder(\n  // Let the ListView know how many items it needs to build.\n  itemCount: items.length,\n  // Provide a builder function. This is where the magic happens.\n  // Convert each item into a widget based on the type of item it is.\n  itemBuilder: (context, index) {\n    final item = items[index];\n\n    return ListTile(\n      title: item.buildTitle(context),\n      subtitle: item.buildSubtitle(context),\n    );\n  },\n)",
        hasImage: false,
      ),
      AppLesson(
        title: "Spaced Items",
        body: "title: List with spaced items\ndescription: How to create a list with spaced or expanded items\n\nPerhaps you want to create a list where all list items\nare spaced evenly, so that the items take up the visible space.\nFor example, the four items in the following image are spaced evenly,\nwith \"Item 0\" at the top, and \"Item 3\" at the bottom.\n\n{:.site-mobile-screenshot}\n\nAt the same time, you might want to allow users\nto scroll through the list when the list of items won't fit,\nmaybe because a device is too small, a user resized a window,\nor the number of items exceeds the screen size.\n\n{:.site-mobile-screenshot}\n\nTypically, you use [Spacer][] to tune the spacing between widgets,\nor [Expanded][] to expand a widget to fill the available space.\nHowever, these solutions are not possible inside scrollable widgets,\nbecause they need a finite height constraint.\n\nThis recipe demonstrates how to use [LayoutBuilder][] and [ConstrainedBox][]\nto space out list items evenly when there is enough space, and to allow\nusers to scroll when there is not enough space,\nusing the following steps:\nAdd a [LayoutBuilder][] with a [SingleChildScrollView][].\nAdd a [ConstrainedBox][] inside the [SingleChildScrollView][].\nCreate a [Column][] with spaced items.\nAdd a LayoutBuilder with a SingleChildScrollView\n\nStart by creating a [LayoutBuilder][]. You need to provide\na builder callback function with two parameters:\nThe [BuildContext][] provided by the [LayoutBuilder][].\nThe [BoxConstraints][] of the parent widget.\n\nIn this recipe, you won't be using the [BuildContext][],\nbut you will need the [BoxConstraints][] in the next step.\n\nInside the builder function, return a [SingleChildScrollView][].\nThis widget ensures that the child widget can be scrolled,\neven when the parent container is too small.\n\nAdd a ConstrainedBox inside the SingleChildScrollView\n\nIn this step, add a [ConstrainedBox][]\nas the child of the [SingleChildScrollView][].\n\nThe [ConstrainedBox][] widget imposes additional constraints to its child.\n\nConfigure the constraint by setting the minHeight parameter to be\nthe maxHeight of the [LayoutBuilder][] constraints.\n\nThis ensures that the child widget\nis constrained to have a minimum height equal to the available\nspace provided by the [LayoutBuilder][] constraints,\nnamely the maximum height of the [BoxConstraints][].\n\nHowever, you don't set the maxHeight parameter,\nbecause you need to allow the child to be larger\nthan the [LayoutBuilder][] size,\nin case the items don't fit the screen.\nCreate a Column with spaced items\n\nFinally, add a [Column][] as the child of the [ConstrainedBox][].\n\nTo space the items evenly,\nset the mainAxisAlignment to MainAxisAlignment.spaceBetween.\n\nAlternatively, you can use the [Spacer][] widget\nto tune the spacing between the items,\nor the [Expanded][] widget, if you want one widget to take more space than others.\n\nFor that, you have to wrap the [Column] with an [IntrinsicHeight][] widget,\nwhich forces the [Column][] widget to size itself to a minimum height,\ninstead of expanding infinitely.\n\n:::tip\nPlay around with different devices, resizing the app,\nor resizing the browser window, and see how the item list adapts\nto the available space.\n:::\nInteractive example\n\nThis example shows a list of items that are spaced evenly within a column.\nThe list can be scrolled up and down when the items don't fit the screen.\nThe number of items is defined by the variable items,\nchange this value to see what happens when the items won't fit the screen.\n\ndartpad title=\"Flutter Spaced Items hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const SpacedItemsList());\n\nclass SpacedItemsList extends StatelessWidget {\n  const SpacedItemsList({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const items = 4;\n\n    return MaterialApp(\n      title: 'Flutter Demo',\n      debugShowCheckedModeBanner: false,\n      theme: ThemeData(\n        colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple),\n        cardTheme: CardThemeData(color: Colors.blue.shade50),\n      ),\n      home: Scaffold(\n        body: LayoutBuilder(\n          builder: (context, constraints) {\n            return SingleChildScrollView(\n              child: ConstrainedBox(\n                constraints: BoxConstraints(minHeight: constraints.maxHeight),\n                child: Column(\n                  mainAxisAlignment: MainAxisAlignment.spaceBetween,\n                  crossAxisAlignment: CrossAxisAlignment.stretch,\n                  children: List.generate(\n                    items,\n                    (index) => ItemWidget(text: 'Item \$index'),\n                  ),\n                ),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass ItemWidget extends StatelessWidget {\n  const ItemWidget({super.key, required this.text});\n\n  final String text;\n\n  @override\n  Widget build(BuildContext context) {\n    return Card(\n      child: SizedBox(height: 100, child: Center(child: Text(text))),\n    );\n  }\n}",
        codeSnippet: "LayoutBuilder(\n  builder: (context, constraints) {\n    return SingleChildScrollView(child: Placeholder());\n  },\n);\n\nLayoutBuilder(\n  builder: (context, constraints) {\n    return SingleChildScrollView(\n      child: ConstrainedBox(\n        constraints: BoxConstraints(minHeight: constraints.maxHeight),\n        child: Placeholder(),\n      ),\n    );\n  },\n);\n\nLayoutBuilder(\n  builder: (context, constraints) {\n    return SingleChildScrollView(\n      child: ConstrainedBox(\n        constraints: BoxConstraints(minHeight: constraints.maxHeight),\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.spaceBetween,\n          children: [\n            ItemWidget(text: 'Item 1'),\n            ItemWidget(text: 'Item 2'),\n            ItemWidget(text: 'Item 3'),\n          ],\n        ),\n      ),\n    );\n  },\n);\n\nLayoutBuilder(\n  builder: (context, constraints) {\n    return SingleChildScrollView(\n      child: ConstrainedBox(\n        constraints: BoxConstraints(minHeight: constraints.maxHeight),\n        child: IntrinsicHeight(\n          child: Column(\n            children: [\n              ItemWidget(text: 'Item 1'),\n              Spacer(),\n              ItemWidget(text: 'Item 2'),\n              Expanded(child: ItemWidget(text: 'Item 3')),\n            ],\n          ),\n        ),\n      ),\n    );\n  },\n);",
        hasImage: true,
      ),
      AppLesson(
        title: "Error Reporting",
        body: "title: Report errors to a service\ndescription: How to keep track of errors that users encounter.\n\nWhile one always tries to create apps that are free of bugs,\nthey're sure to crop up from time to time.\nSince buggy apps lead to unhappy users and customers,\nit's important to understand how often your users\nexperience bugs and where those bugs occur.\nThat way, you can prioritize the bugs with the\nhighest impact and work to fix them.\n\nHow can you determine how often your users experiences bugs?\nWhenever an error occurs, create a report containing the\nerror that occurred and the associated stacktrace.\nYou can then send the report to an error tracking\nservice, such as [Bugsnag][], [Datadog][],\n[Firebase Crashlytics][], [Rollbar][], or Sentry.\n\nThe error tracking service aggregates all of the crashes your users\nexperience and groups them together. This allows you to know how often your\napp fails and where the users run into trouble.\n\nIn this recipe, learn how to report errors to the\n[Sentry][] crash reporting service using\nthe following steps:\nGet a DSN from Sentry.\nImport the Flutter Sentry package\nInitialize the Sentry SDK\nCapture errors programmatically\nGet a DSN from Sentry\n\nBefore reporting errors to Sentry, you need a \"DSN\" to uniquely identify\nyour app with the Sentry.io service.\n\nTo get a DSN, use the following steps:\n[Create an account with Sentry][].\nLog in to the account.\nCreate a new Flutter project.\nCopy the code snippet that includes the DSN.\nImport the Sentry package\n\nImport the [sentry_flutter][] package into the app.\nThe sentry package makes it easier to send\nerror reports to the Sentry error tracking service.\n\nTo add the sentry_flutter package as a dependency,\nrun flutter pub add:\nInitialize the Sentry SDK\n\nInitialize the SDK to capture different unhandled errors automatically:\n\nAlternatively, you can pass the DSN to Flutter using the dart-define tag:\nWhat does that give me?\n\nThis is all you need for Sentry to\ncapture unhandled errors in Dart and native layers.\nThis includes Swift, Objective-C, C, and C++ on iOS, and\nJava, Kotlin, C, and C++ on Android.\nCapture errors programmatically\n\nBesides the automatic error reporting that Sentry generates by\nimporting and initializing the SDK,\nyou can use the API to report errors to Sentry:\n\nFor more information, see the [Sentry API][] docs on pub.dev.\nLearn more\n\nExtensive documentation about using the Sentry SDK can be found on [Sentry's site][].\nComplete example\n\nTo view a working example,\nsee the [Sentry flutter example][] app.",
        codeSnippet: "\$ flutter pub add sentry_flutter\n\nimport 'package:flutter/widgets.dart';\nimport 'package:sentry_flutter/sentry_flutter.dart';\n\nFuture<void> main() async {\n  await SentryFlutter.init(\n    (options) => options.dsn = 'https://example@sentry.io/example',\n    appRunner: () => runApp(const MyApp()),\n  );\n}\n\n--dart-define SENTRY_DSN=https://example@sentry.io/example\n\nawait Sentry.captureException(exception, stackTrace: stackTrace);",
        hasImage: false,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter maintenance cookbook\nshortTitle: Maintenance\ndescription: A catalog of recipes covering maintenance of Flutter apps.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Hero Animations",
        body: "title: Animate a widget across screens\ndescription: How to animate a widget from one screen to another\n\nIt's often helpful to guide users through an app as they navigate from screen\nto screen. A common technique to lead users through an app is to animate a\nwidget from one screen to the next. This creates a visual anchor connecting\nthe two screens.\n\nUse the [Hero][] widget\nto animate a widget from one screen to the next.\nThis recipe uses the following steps:\nCreate two screens showing the same image.\nAdd a Hero widget to the first screen.\nAdd a Hero widget to the second screen.\nCreate two screens showing the same image\n\nIn this example, display the same image on both screens.\nAnimate the image from the first screen to the second screen when\nthe user taps the image. For now, create the visual structure;\nhandle animations in the next steps.\n\n:::note\nThis example builds upon the\n[Navigate to a new screen and back][]\nand [Handle taps][] recipes.\n:::\n\nAdd a Hero widget to the first screen\n\nTo connect the two screens together with an animation, wrap\nthe Image widget on both screens in a Hero widget.\nThe Hero widget requires two arguments:\n\ntag\n: An object that identifies the Hero.\n  It must be the same on both screens.\n\nchild\n: The widget to animate across screens.\n\n{% comment %}\nRegEx removes the first \"child\" property name and removed the trailing comma at the end\n{% endcomment %}\n\nAdd a Hero widget to the second screen\n\nTo complete the connection with the first screen,\nwrap the Image on the second screen with a Hero\nwidget that has the same tag as the Hero in the first screen.\n\nAfter applying the Hero widget to the second screen,\nthe animation between screens just works.\n\n{% comment %}\nRegEx removes the first \"child\" property name and removed the trailing comma at the end\n{% endcomment %}\n\n:::note\nThis code is identical to what you have on the first screen.\nAs a best practice, create a reusable widget instead of\nrepeating code. This example uses identical code for both\nwidgets, for simplicity.\n:::\nInteractive example\n\ndartpad title=\"Flutter Hero animation hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const HeroApp());\n\nclass HeroApp extends StatelessWidget {\n  const HeroApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const MaterialApp(title: 'Transition Demo', home: MainScreen());\n  }\n}\n\nclass MainScreen extends StatelessWidget {\n  const MainScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Main Screen')),\n      body: GestureDetector(\n        onTap: () {\n          Navigator.push(\n            context,\n            MaterialPageRoute(\n              builder: (context) {\n                return const DetailScreen();\n              },\n            ),\n          );\n        },\n        child: Hero(\n          tag: 'imageHero',\n          child: Image.network('https://picsum.photos/250?image=9'),\n        ),\n      ),\n    );\n  }\n}\n\nclass DetailScreen extends StatelessWidget {\n  const DetailScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: GestureDetector(\n        onTap: () {\n          Navigator.pop(context);\n        },\n        child: Center(\n          child: Hero(\n            tag: 'imageHero',\n            child: Image.network('https://picsum.photos/250?image=9'),\n          ),\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "import 'package:flutter/material.dart';\n\nclass MainScreen extends StatelessWidget {\n  const MainScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Main Screen')),\n      body: GestureDetector(\n        onTap: () {\n          Navigator.push(\n            context,\n            MaterialPageRoute<void>(\n              builder: (context) {\n                return const DetailScreen();\n              },\n            ),\n          );\n        },\n        child: Image.network('https://picsum.photos/250?image=9'),\n      ),\n    );\n  }\n}\n\nclass DetailScreen extends StatelessWidget {\n  const DetailScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      body: GestureDetector(\n        onTap: () {\n          Navigator.pop(context);\n        },\n        child: Center(\n          child: Image.network('https://picsum.photos/250?image=9'),\n        ),\n      ),\n    );\n  }\n}\n\nHero(\n  tag: 'imageHero',\n  child: Image.network('https://picsum.photos/250?image=9'),\n)\n\nHero(\n  tag: 'imageHero',\n  child: Image.network('https://picsum.photos/250?image=9'),\n)",
        hasImage: false,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter navigation cookbook\nshortTitle: Navigation\ndescription: A catalog of recipes for handling navigation in your Flutter app.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Named Routes",
        body: "title: Navigate with named routes\ndescription: How to implement named routes for navigating between screens.\n\n:::note\nNamed routes are no longer recommended for most\napplications. For more information, see\n[Limitations][] in the [navigation overview][] page.\n:::\n\nIn the [Navigate to a new screen and back][] recipe,\nyou learned how to navigate to a new screen by creating a new route and\npushing it to the [Navigator][].\n\nHowever, if you need to navigate to the same screen in many parts\nof your app, this approach can result in code duplication.\nThe solution is to define a named route,\nand use the named route for navigation.\n\nTo work with named routes,\nuse the [Navigator.pushNamed()][] function.\nThis example replicates the functionality from the original recipe,\ndemonstrating how to use named routes using the following steps:\nCreate two screens.\nDefine the routes.\nNavigate to the second screen using Navigator.pushNamed().\nReturn to the first screen using Navigator.pop().\nCreate two screens\n\nFirst, create two screens to work with. The first screen contains a\nbutton that navigates to the second screen. The second screen contains a\nbutton that navigates back to the first.\n\nDefine the routes\n\nNext, define the routes by providing additional properties\nto the [MaterialApp][] constructor: the initialRoute\nand the routes themselves.\n\nThe initialRoute property defines which route the app should start with.\nThe routes property defines the available named routes and the widgets\nto build when navigating to those routes.\n\n{% comment %}\nRegEx removes the trailing comma\n{% endcomment %}\n\n:::warning\nWhen using initialRoute, don't define a home property.\n:::\nNavigate to the second screen\n\nWith the widgets and routes in place, trigger navigation by using the\n[Navigator.pushNamed()][] method.\nThis tells Flutter to build the widget defined in the\nroutes table and launch the screen.\n\nIn the build() method of the FirstScreen widget, update the onPressed()\ncallback:\n\n{% comment %}\nRegEx removes the trailing comma\n{% endcomment %}\n\nReturn to the first screen\n\nTo navigate back to the first screen, use the\n[Navigator.pop()][] function.\n\n{% comment %}\nRegEx removes the trailing comma\n{% endcomment %}\n\nInteractive example\n\ndartpad title=\"Flutter Named Routes hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(\n    MaterialApp(\n      title: 'Named Routes Demo',\n      // Start the app with the \"/\" named route. In this case, the app starts\n      // on the FirstScreen widget.\n      initialRoute: '/',\n      routes: {\n        // When navigating to the \"/\" route, build the FirstScreen widget.\n        '/': (context) => const FirstScreen(),\n        // When navigating to the \"/second\" route, build the SecondScreen widget.\n        '/second': (context) => const SecondScreen(),\n      },\n    ),\n  );\n}\n\nclass FirstScreen extends StatelessWidget {\n  const FirstScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('First Screen')),\n      body: Center(\n        child: ElevatedButton(\n          // Within the FirstScreen widget\n          onPressed: () {\n            // Navigate to the second screen using a named route.\n            Navigator.pushNamed(context, '/second');\n          },\n          child: const Text('Launch screen'),\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondScreen extends StatelessWidget {\n  const SecondScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Second Screen')),\n      body: Center(\n        child: ElevatedButton(\n          // Within the SecondScreen widget\n          onPressed: () {\n            // Navigate back to the first screen by popping the current route\n            // off the stack.\n            Navigator.pop(context);\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "import 'package:flutter/material.dart';\n\nclass FirstScreen extends StatelessWidget {\n  const FirstScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('First Screen')),\n      body: Center(\n        child: ElevatedButton(\n          onPressed: () {\n            // Navigate to the second screen when tapped.\n          },\n          child: const Text('Launch screen'),\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondScreen extends StatelessWidget {\n  const SecondScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Second Screen')),\n      body: Center(\n        child: ElevatedButton(\n          onPressed: () {\n            // Navigate back to first screen when tapped.\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}\n\nMaterialApp(\n  title: 'Named Routes Demo',\n  // Start the app with the \"/\" named route. In this case, the app starts\n  // on the FirstScreen widget.\n  initialRoute: '/',\n  routes: {\n    // When navigating to the \"/\" route, build the FirstScreen widget.\n    '/': (context) => const FirstScreen(),\n    // When navigating to the \"/second\" route, build the SecondScreen widget.\n    '/second': (context) => const SecondScreen(),\n  },\n)\n\n// Within the `FirstScreen` widget\nonPressed: () {\n  // Navigate to the second screen using a named route.\n  Navigator.pushNamed(context, '/second');\n}\n\n// Within the SecondScreen widget\nonPressed: () {\n  // Navigate back to the first screen by popping the current route\n  // off the stack.\n  Navigator.pop(context);\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Navigate With Arguments",
        body: "title: Pass arguments to a named route\ndescription: How to pass arguments to a named route.\n\nThe [Navigator][] provides the ability to navigate\nto a named route from any part of an app using\na common identifier.\nIn some cases, you might also need to pass arguments to a\nnamed route. For example, you might wish to navigate to the /user route and\npass information about the user to that route.\n\n:::note\nNamed routes are no longer recommended for most\napplications. For more information, see\n[Limitations][] in the [navigation overview][] page.\n:::\n\nYou can accomplish this task using the arguments parameter of the\n[Navigator.pushNamed()][] method. Extract the arguments using the\n[ModalRoute.of()][] method or inside an [onGenerateRoute()][]\nfunction provided to the [MaterialApp][] or [CupertinoApp][]\nconstructor.\n\nThis recipe demonstrates how to pass arguments to a named\nroute and read the arguments using ModalRoute.of()\nand onGenerateRoute() using the following steps:\nDefine the arguments you need to pass.\nCreate a widget that extracts the arguments.\nRegister the widget in the routes table.\nNavigate to the widget.\nDefine the arguments you need to pass\n\nFirst, define the arguments you need to pass to the new route.\nIn this example, pass two pieces of data:\nThe title of the screen and a message.\n\nTo pass both pieces of data, create a class that stores this information.\n\nCreate a widget that extracts the arguments\n\nNext, create a widget that extracts and displays the\ntitle and message from the ScreenArguments.\nTo access the ScreenArguments,\nuse the [ModalRoute.of()][] method.\nThis method returns the current route with the arguments.\n\nRegister the widget in the routes table\n\nNext, add an entry to the routes provided to the MaterialApp widget. The\nroutes define which widget should be created based on the name of the route.\n\n{% comment %}\nRegEx removes the return statement and adds the closing parenthesis at the end\n{% endcomment %}\n\nNavigate to the widget\n\nFinally, navigate to the ExtractArgumentsScreen\nwhen a user taps a button using [Navigator.pushNamed()][].\nProvide the arguments to the route via the arguments property. The\nExtractArgumentsScreen extracts the title and message from these\narguments.\n\nAlternatively, extract the arguments using onGenerateRoute\n\nInstead of extracting the arguments directly inside the widget, you can also\nextract the arguments inside an [onGenerateRoute()][]\nfunction and pass them to a widget.\n\nThe onGenerateRoute() function creates the correct route based on the given\n[RouteSettings][].\n\n{% comment %}\nRegEx removes the return statement, removed \"routes\" property and adds the closing parenthesis at the end\n{% endcomment %}\nInteractive example\n\ndartpad title=\"Flutter complete navigation hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      routes: {\n        ExtractArgumentsScreen.routeName: (context) =>\n            const ExtractArgumentsScreen(),\n      },\n      // Provide a function to handle named routes.\n      // Use this function to identify the named\n      // route being pushed, and create the correct\n      // Screen.\n      onGenerateRoute: (settings) {\n        // If you push the PassArguments route\n        if (settings.name == PassArgumentsScreen.routeName) {\n          // Cast the arguments to the correct\n          // type: ScreenArguments.\n          final args = settings.arguments as ScreenArguments;\n\n          // Then, extract the required data from\n          // the arguments and pass the data to the\n          // correct screen.\n          return MaterialPageRoute(\n            builder: (context) {\n              return PassArgumentsScreen(\n                title: args.title,\n                message: args.message,\n              );\n            },\n          );\n        }\n        // The code only supports\n        // PassArgumentsScreen.routeName right now.\n        // Other values need to be implemented if we\n        // add them. The assertion here will help remind\n        // us of that higher up in the call stack, since\n        // this assertion would otherwise fire somewhere\n        // in the framework.\n        assert(false, 'Need to implement \${settings.name}');\n        return null;\n      },\n      title: 'Navigation with Arguments',\n      home: const HomeScreen(),\n    );\n  }\n}\n\nclass HomeScreen extends StatelessWidget {\n  const HomeScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Home Screen')),\n      body: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            // A button that navigates to a named route.\n            // The named route extracts the arguments\n            // by itself.\n            ElevatedButton(\n              onPressed: () {\n                // When the user taps the button,\n                // navigate to a named route and\n                // provide the arguments as an optional\n                // parameter.\n                Navigator.pushNamed(\n                  context,\n                  ExtractArgumentsScreen.routeName,\n                  arguments: ScreenArguments(\n                    'Extract Arguments Screen',\n                    'This message is extracted in the build method.',\n                  ),\n                );\n              },\n              child: const Text('Navigate to screen that extracts arguments'),\n            ),\n            // A button that navigates to a named route.\n            // For this route, extract the arguments in\n            // the onGenerateRoute function and pass them\n            // to the screen.\n            ElevatedButton(\n              onPressed: () {\n                // When the user taps the button, navigate\n                // to a named route and provide the arguments\n                // as an optional parameter.\n                Navigator.pushNamed(\n                  context,\n                  PassArgumentsScreen.routeName,\n                  arguments: ScreenArguments(\n                    'Accept Arguments Screen',\n                    'This message is extracted in the onGenerateRoute '\n                        'function.',\n                  ),\n                );\n              },\n              child: const Text('Navigate to a named that accepts arguments'),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\n// A Widget that extracts the necessary arguments from\n// the ModalRoute.\nclass ExtractArgumentsScreen extends StatelessWidget {\n  const ExtractArgumentsScreen({super.key});\n\n  static const routeName = '/extractArguments';\n\n  @override\n  Widget build(BuildContext context) {\n    // Extract the arguments from the current ModalRoute\n    // settings and cast them as ScreenArguments.\n    final args = ModalRoute.of(context)!.settings.arguments as ScreenArguments;\n\n    return Scaffold(\n      appBar: AppBar(title: Text(args.title)),\n      body: Center(child: Text(args.message)),\n    );\n  }\n}\n\n// A Widget that accepts the necessary arguments via the\n// constructor.\nclass PassArgumentsScreen extends StatelessWidget {\n  static const routeName = '/passArguments';\n\n  final String title;\n  final String message;\n\n  // This Widget accepts the arguments as constructor\n  // parameters. It does not extract the arguments from\n  // the ModalRoute.\n  //\n  // The arguments are extracted by the onGenerateRoute\n  // function provided to the MaterialApp widget.\n  const PassArgumentsScreen({\n    super.key,\n    required this.title,\n    required this.message,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: Text(title)),\n      body: Center(child: Text(message)),\n    );\n  }\n}\n\n// You can pass any object to the arguments parameter.\n// In this example, create a class that contains both\n// a customizable title and message.\nclass ScreenArguments {\n  final String title;\n  final String message;\n\n  ScreenArguments(this.title, this.message);\n}",
        codeSnippet: "// You can pass any object to the arguments parameter.\n// In this example, create a class that contains both\n// a customizable title and message.\nclass ScreenArguments {\n  final String title;\n  final String message;\n\n  ScreenArguments(this.title, this.message);\n}\n\n// A Widget that extracts the necessary arguments from\n// the ModalRoute.\nclass ExtractArgumentsScreen extends StatelessWidget {\n  const ExtractArgumentsScreen({super.key});\n\n  static const routeName = '/extractArguments';\n\n  @override\n  Widget build(BuildContext context) {\n    // Extract the arguments from the current ModalRoute\n    // settings and cast them as ScreenArguments.\n    final args = ModalRoute.of(context)!.settings.arguments as ScreenArguments;\n\n    return Scaffold(\n      appBar: AppBar(title: Text(args.title)),\n      body: Center(child: Text(args.message)),\n    );\n  }\n}\n\nMaterialApp(\n  routes: {\n    ExtractArgumentsScreen.routeName: (context) =>\n        const ExtractArgumentsScreen(),\n  },\n)\n\n// A button that navigates to a named route.\n// The named route extracts the arguments\n// by itself.\nElevatedButton(\n  onPressed: () {\n    // When the user taps the button,\n    // navigate to a named route and\n    // provide the arguments as an optional\n    // parameter.\n    Navigator.pushNamed(\n      context,\n      ExtractArgumentsScreen.routeName,\n      arguments: ScreenArguments(\n        'Extract Arguments Screen',\n        'This message is extracted in the build method.',\n      ),\n    );\n  },\n  child: const Text('Navigate to screen that extracts arguments'),\n),\n\nMaterialApp(\n  // Provide a function to handle named routes.\n  // Use this function to identify the named\n  // route being pushed, and create the correct\n  // Screen.\n  onGenerateRoute: (settings) {\n    // If you push the PassArguments route\n    if (settings.name == PassArgumentsScreen.routeName) {\n      // Cast the arguments to the correct\n      // type: ScreenArguments.\n      final args = settings.arguments as ScreenArguments;\n\n      // Then, extract the required data from\n      // the arguments and pass the data to the\n      // correct screen.\n      return MaterialPageRoute(\n        builder: (context) {\n          return PassArgumentsScreen(\n            title: args.title,\n            message: args.message,\n          );\n        },\n      );\n    }\n    // The code only supports\n    // PassArgumentsScreen.routeName right now.\n    // Other values need to be implemented if we\n    // add them. The assertion here will help remind\n    // us of that higher up in the call stack, since\n    // this assertion would otherwise fire somewhere\n    // in the framework.\n    assert(false, 'Need to implement \${settings.name}');\n    return null;\n  },\n)",
        hasImage: false,
      ),
      AppLesson(
        title: "Navigation Basics",
        body: "title: Navigate to a new screen and back\ndescription: How to navigate between routes.\n\nMost apps contain several screens for displaying different\ntypes of information. For example, an app might have a\nscreen that displays products. When the user taps the image\nof a product, a new screen displays details about the\nproduct.\n\n:::note Terminology\nIn Flutter, screens and pages are called routes.\nThe remainder of this recipe refers to routes.\n:::\n\nIn Android, a route is equivalent to an Activity.\nIn iOS, a route is equivalent to a ViewController.\nIn Flutter, a route is just a widget.\n\nThis recipe uses the [Navigator][] to navigate to a new route.\n\nThe next few sections show how to navigate between two routes,\nusing these steps:\nCreate two routes.\nNavigate to the second route using Navigator.push().\nReturn to the first route using Navigator.pop().\nCreate two routes\n\nFirst, create two routes to work with. Since this is a basic example,\neach route contains only a single button. Tapping the button on the\nfirst route navigates to the second route. Tapping the button on the\nsecond route returns to the first route.\n\nFirst, set up the visual structure:\n\nNavigate to the second route using Navigator.push()\n\nTo switch to a new route, use the [Navigator.push()][]\nmethod. The push() method adds a Route to the stack of routes managed by\nthe Navigator. Where does the Route come from?\nYou can create your own, or use  a platform-specific route\nsuch as [MaterialPageRoute][] or [CupertinoPageRoute][].\nA platform-specific route is useful because it transitions\nto the new route using a platform-specific animation.\n\nIn the build() method of the FirstRoute widget,\nupdate the onPressed() callback:\n\nReturn to the first route using Navigator.pop()\n\nHow do you close the second route and return to the first?\nBy using the [Navigator.pop()][] method.\nThe pop() method removes the current Route from the stack of\nroutes managed by the Navigator.\n\nTo implement a return to the original route, update the onPressed()\ncallback in the SecondRoute widget:\n\nInteractive example\n\ndartpad title=\"Flutter navigation hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(const MaterialApp(title: 'Navigation Basics', home: FirstRoute()));\n}\n\nclass FirstRoute extends StatelessWidget {\n  const FirstRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('First Route')),\n      body: Center(\n        child: ElevatedButton(\n          child: const Text('Open route'),\n          onPressed: () {\n            Navigator.push(\n              context,\n              MaterialPageRoute(\n                builder: (context) => const SecondRoute(),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondRoute extends StatelessWidget {\n  const SecondRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Second Route')),\n      body: Center(\n        child: ElevatedButton(\n          onPressed: () {\n            Navigator.pop(context);\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}\ndartpad title=\"Flutter Cupertino theme hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/cupertino.dart';\n\nvoid main() {\n  runApp(const CupertinoApp(title: 'Navigation Basics', home: FirstRoute()));\n}\n\nclass FirstRoute extends StatelessWidget {\n  const FirstRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return CupertinoPageScaffold(\n      navigationBar: const CupertinoNavigationBar(middle: Text('First Route')),\n      child: Center(\n        child: CupertinoButton(\n          child: const Text('Open route'),\n          onPressed: () {\n            Navigator.push(\n              context,\n              CupertinoPageRoute(\n                builder: (context) => const SecondRoute(),\n              ),\n            );\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondRoute extends StatelessWidget {\n  const SecondRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return CupertinoPageScaffold(\n      navigationBar: const CupertinoNavigationBar(middle: Text('Second Route')),\n      child: Center(\n        child: CupertinoButton(\n          onPressed: () {\n            Navigator.pop(context);\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}\n\n\n\nAdditional navigation methods\n\nThe recipe in this topic shows you one way to navigate to a new screen and\nback to the previous scene, using the [push] and [pop] methods in the\n[Navigator] class, but there are several other Navigator static methods that\nyou can use. Here are a few of them:\n\n   [pushAndRemoveUntil]: Adds a navigation route to the stack and then removes\n    the most recent routes from the stack until a condition is met.\n   [pushReplacement]: Replaces the current route on the top of the\n    stack with a new one.\n   [replace]: Replace a route on the stack with another route.\n   [replaceRouteBelow]: Replace the route below a specific route on the stack.\n   [popUntil]: Removes the most recent routes that were added to the stack of\n    navigation routes until a condition is met.\n   [removeRoute]: Remove a specific route from the stack.\n   [removeRouteBelow]: Remove the route below a specific route on the\n    stack.\n   [restorablePush]: Restore a route that was removed from the stack.",
        codeSnippet: "class FirstRoute extends StatelessWidget {\n  const FirstRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('First Route')),\n      body: Center(\n        child: ElevatedButton(\n          child: const Text('Open route'),\n          onPressed: () {\n            // Navigate to second route when tapped.\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondRoute extends StatelessWidget {\n  const SecondRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Second Route')),\n      body: Center(\n        child: ElevatedButton(\n          onPressed: () {\n            // Navigate back to first route when tapped.\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}\n\nclass FirstRoute extends StatelessWidget {\n  const FirstRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return CupertinoPageScaffold(\n      navigationBar: const CupertinoNavigationBar(middle: Text('First Route')),\n      child: Center(\n        child: CupertinoButton(\n          child: const Text('Open route'),\n          onPressed: () {\n            // Navigate to second route when tapped.\n          },\n        ),\n      ),\n    );\n  }\n}\n\nclass SecondRoute extends StatelessWidget {\n  const SecondRoute({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return CupertinoPageScaffold(\n      navigationBar: const CupertinoNavigationBar(middle: Text('Second Route')),\n      child: Center(\n        child: CupertinoButton(\n          onPressed: () {\n            // Navigate back to first route when tapped.\n          },\n          child: const Text('Go back!'),\n        ),\n      ),\n    );\n  }\n}\n\n// Within the `FirstRoute` widget:\nonPressed: () {\n  Navigator.push(\n    context,\n    MaterialPageRoute<void>(\n      builder: (context) => const SecondRoute(),\n    ),\n  );\n}\n\n// Within the `FirstRoute` widget:\nonPressed: () {\n  Navigator.push(\n    context,\n    CupertinoPageRoute<void>(\n      builder: (context) => const SecondRoute(),\n    ),\n  );\n}\n\n// Within the SecondRoute widget\nonPressed: () {\n  Navigator.pop(context);\n}\n\n<noscript>\n  <img src=\"/assets/images/docs/cookbook/navigation-basics.webp\" alt=\"Navigation Basics Demo\" class=\"site-mobile-screenshot\" />\n</noscript>\n\n</Tab>\n\n<Tab name=\"iOS\">\n\n<?code-excerpt \"lib/main_cupertino.dart\"?>",
        hasImage: false,
      ),
      AppLesson(
        title: "Passing Data",
        body: "title: Send data to a new screen\ndescription: How to pass data to a new route.\n\nOften, you not only want to navigate to a new screen,\nbut also pass data to the screen as well.\nFor example, you might want to pass information about\nthe item that's been tapped.\n\nRemember: Screens are just widgets.\nIn this example, create a list of todos.\nWhen a todo is tapped, navigate to a new screen (widget) that\ndisplays information about the todo.\nThis recipe uses the following steps:\nDefine a todo class.\nDisplay a list of todos.\nCreate a detail screen that can display information about a todo.\nNavigate and pass data to the detail screen.\nDefine a todo class\n\nFirst, you need a simple way to represent todos. For this example,\ncreate a class that contains two pieces of data: the title and description.\n\nCreate a list of todos\n\nSecond, display a list of todos. In this example, generate\n20 todos and show them using a ListView.\nFor more information on working with lists,\nsee the [Use lists][] recipe.\nGenerate the list of todos\n\nDisplay the list of todos using a ListView\n\nSo far, so good.\nThis generates 20 todos and displays them in a ListView.\nCreate a Todo screen to display the list\n\nFor this, we create a StatelessWidget. We call it TodosScreen.\nSince the contents of this page won't change during runtime,\nwe'll have to require the list\nof todos within the scope of this widget.\n\nWe pass in our ListView.builder as body of the widget we're returning to build().\nThis'll render the list on to the screen for you to get going!\n\nWith Flutter's default styling, you're good to go without sweating about\nthings that you'd like to do later on!\nCreate a detail screen to display information about a todo\n\nNow, create the second screen. The title of the screen contains the\ntitle of the todo, and the body of the screen shows the description.\n\nSince the detail screen is a normal StatelessWidget,\nrequire the user to enter a Todo in the UI.\nThen, build the UI using the given todo.\n\nNavigate and pass data to the detail screen\n\nWith a DetailScreen in place,\nyou're ready to perform the Navigation.\nIn this example, navigate to the DetailScreen when a user\ntaps a todo in the list. Pass the todo to the DetailScreen.\n\nTo capture the user's tap in the TodosScreen, write an [onTap()][]\ncallback for the ListTile widget. Within the onTap() callback,\nuse the [Navigator.push()][] method.\n\nInteractive example\n\ndartpad title=\"Flutter passing data hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nclass Todo {\n  final String title;\n  final String description;\n\n  const Todo(this.title, this.description);\n}\n\nvoid main() {\n  runApp(\n    MaterialApp(\n      title: 'Passing Data',\n      home: TodosScreen(\n        todos: List.generate(\n          20,\n          (i) => Todo(\n            'Todo \$i',\n            'A description of what needs to be done for Todo \$i',\n          ),\n        ),\n      ),\n    ),\n  );\n}\n\nclass TodosScreen extends StatelessWidget {\n  const TodosScreen({super.key, required this.todos});\n\n  final List todos;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Todos')),\n      body: ListView.builder(\n        itemCount: todos.length,\n        itemBuilder: (context, index) {\n          return ListTile(\n            title: Text(todos[index].title),\n            // When a user taps the ListTile, navigate to the DetailScreen.\n            // Notice that you're not only creating a DetailScreen, you're\n            // also passing the current todo through to it.\n            onTap: () {\n              Navigator.push(\n                context,\n                MaterialPageRoute(\n                  builder: (context) => DetailScreen(todo: todos[index]),\n                ),\n              );\n            },\n          );\n        },\n      ),\n    );\n  }\n}\n\nclass DetailScreen extends StatelessWidget {\n  // In the constructor, require a Todo.\n  const DetailScreen({super.key, required this.todo});\n\n  // Declare a field that holds the Todo.\n  final Todo todo;\n\n  @override\n  Widget build(BuildContext context) {\n    // Use the Todo to create the UI.\n    return Scaffold(\n      appBar: AppBar(title: Text(todo.title)),\n      body: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Text(todo.description),\n      ),\n    );\n  }\n}\ndart\nclass DetailScreen extends StatelessWidget {\n  const DetailScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final todo = ModalRoute.of(context)!.settings.arguments as Todo;\n\n    // Use the Todo to create the UI.\n    return Scaffold(\n      appBar: AppBar(title: Text(todo.title)),\n      body: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Text(todo.description),\n      ),\n    );\n  }\n}\ndart\nListView.builder(\n  itemCount: todos.length,\n  itemBuilder: (context, index) {\n    return ListTile(\n      title: Text(todos[index].title),\n      // When a user taps the ListTile, navigate to the DetailScreen.\n      // Notice that you're not only creating a DetailScreen, you're\n      // also passing the current todo through to it.\n      onTap: () {\n        Navigator.push(\n          context,\n          MaterialPageRoute(\n            builder: (context) => const DetailScreen(),\n            // Pass the arguments as part of the RouteSettings. The\n            // DetailScreen reads the arguments from these settings.\n            settings: RouteSettings(arguments: todos[index]),\n          ),\n        );\n      },\n    );\n  },\n)\ndart\nimport 'package:flutter/material.dart';\n\nclass Todo {\n  final String title;\n  final String description;\n\n  const Todo(this.title, this.description);\n}\n\nvoid main() {\n  runApp(\n    MaterialApp(\n      title: 'Passing Data',\n      home: TodosScreen(\n        todos: List.generate(\n          20,\n          (i) => Todo(\n            'Todo \$i',\n            'A description of what needs to be done for Todo \$i',\n          ),\n        ),\n      ),\n    ),\n  );\n}\n\nclass TodosScreen extends StatelessWidget {\n  const TodosScreen({super.key, required this.todos});\n\n  final List todos;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Todos')),\n      body: ListView.builder(\n        itemCount: todos.length,\n        itemBuilder: (context, index) {\n          return ListTile(\n            title: Text(todos[index].title),\n            // When a user taps the ListTile, navigate to the DetailScreen.\n            // Notice that you're not only creating a DetailScreen, you're\n            // also passing the current todo through to it.\n            onTap: () {\n              Navigator.push(\n                context,\n                MaterialPageRoute(\n                  builder: (context) => const DetailScreen(),\n                  // Pass the arguments as part of the RouteSettings. The\n                  // DetailScreen reads the arguments from these settings.\n                  settings: RouteSettings(arguments: todos[index]),\n                ),\n              );\n            },\n          );\n        },\n      ),\n    );\n  }\n}\n\nclass DetailScreen extends StatelessWidget {\n  const DetailScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    final todo = ModalRoute.of(context)!.settings.arguments as Todo;\n\n    // Use the Todo to create the UI.\n    return Scaffold(\n      appBar: AppBar(title: Text(todo.title)),\n      body: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Text(todo.description),\n      ),\n    );\n  }\n}",
        codeSnippet: "class Todo {\n  final String title;\n  final String description;\n\n  const Todo(this.title, this.description);\n}\n\nfinal todos = List.generate(\n  20,\n  (i) => Todo(\n    'Todo \$i',\n    'A description of what needs to be done for Todo \$i',\n  ),\n);\n\nListView.builder(\n  itemCount: todos.length,\n  itemBuilder: (context, index) {\n    return ListTile(title: Text(todos[index].title));\n  },\n)\n\nclass TodosScreen extends StatelessWidget {\n  // Requiring the list of todos.\n  const TodosScreen({super.key, required this.todos});\n\n  final List<Todo> todos;\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Todos')),\n      //passing in the ListView.builder\n      body: ListView.builder(\n        itemCount: todos.length,\n        itemBuilder: (context, index) {\n          return ListTile(title: Text(todos[index].title));\n        },\n      ),\n    );\n  }\n}\n\nclass DetailScreen extends StatelessWidget {\n  // In the constructor, require a Todo.\n  const DetailScreen({super.key, required this.todo});\n\n  // Declare a field that holds the Todo.\n  final Todo todo;\n\n  @override\n  Widget build(BuildContext context) {\n    // Use the Todo to create the UI.\n    return Scaffold(\n      appBar: AppBar(title: Text(todo.title)),\n      body: Padding(\n        padding: const EdgeInsets.all(16),\n        child: Text(todo.description),\n      ),\n    );\n  }\n}\n\nbody: ListView.builder(\n  itemCount: todos.length,\n  itemBuilder: (context, index) {\n    return ListTile(\n      title: Text(todos[index].title),\n      // When a user taps the ListTile, navigate to the DetailScreen.\n      // Notice that you're not only creating a DetailScreen, you're\n      // also passing the current todo through to it.\n      onTap: () {\n        Navigator.push(\n          context,\n          MaterialPageRoute<void>(\n            builder: (context) => DetailScreen(todo: todos[index]),\n          ),\n        );\n      },\n    );\n  },\n),\n\n## Alternatively, pass the arguments using RouteSettings\n\nRepeat the first two steps.\n\n### Create a detail screen to extract the arguments\n\nNext, create a detail screen that extracts and displays the title and description from the `Todo`. To access the `Todo`, use the [`ModalRoute.of()`][] method. This method returns the current route with the arguments.\n\n<?code-excerpt \"lib/main_routesettings.dart (DetailScreen)\"?>\n\n### Navigate and pass the arguments to the detail screen\n\nFinally, navigate to the `DetailScreen` when a user taps\na `ListTile` widget using `Navigator.push()`.\nPass the arguments as part of the [`RouteSettings`][].\nThe `DetailScreen` extracts these arguments.\n\n<?code-excerpt \"lib/main_routesettings.dart (builder)\" replace=\"/^body: //g;/^\\),\$/)/g\"?>\n\n### Complete example\n\n<?code-excerpt \"lib/main_routesettings.dart\"?>",
        hasImage: false,
      ),
      AppLesson(
        title: "Returning Data",
        body: "title: Return data from a screen\ndescription: How to return data from a new screen.\n\nIn some cases, you might want to return data from a new screen.\nFor example, say you push a new screen that presents two options to a user.\nWhen the user taps an option, you want to inform the first screen\nof the user's selection so that it can act on that information.\n\nYou can do this with the [Navigator.pop()][]\nmethod using the following steps:\nDefine the home screen\nAdd a button that launches the selection screen\nShow the selection screen with two buttons\nWhen a button is tapped, close the selection screen\nShow a snackbar on the home screen with the selection\nDefine the home screen\n\nThe home screen displays a button. When tapped,\nit launches the selection screen.\n\nAdd a button that launches the selection screen\n\nNow, create the SelectionButton, which does the following:\n\n   Launches the SelectionScreen when it's tapped.\n   Waits for the SelectionScreen to return a result.\n\nShow the selection screen with two buttons\n\nNow, build a selection screen that contains two buttons.\nWhen a user taps a button,\nthat app closes the selection screen and lets the home\nscreen know which button was tapped.\n\nThis step defines the UI.\nThe next step adds code to return data.\n\nWhen a button is tapped, close the selection screen\n\nNow, update the onPressed() callback for both of the buttons.\nTo return data to the first screen,\nuse the [Navigator.pop()][] method,\nwhich accepts an optional second argument called result.\nAny result is returned to the Future in the SelectionButton.\nYep button\n\nNope button\n\nShow a snackbar on the home screen with the selection\n\nNow that you're launching a selection screen and awaiting the result,\nyou'll want to do something with the information that's returned.\n\nIn this case, show a snackbar displaying the result by using the\n_navigateAndDisplaySelection() method in SelectionButton:\n\nInteractive example\n\ndartpad title=\"Flutter Return from Data hands-on example in DartPad\" run=\"true\"\nimport 'package:flutter/material.dart';\n\nvoid main() {\n  runApp(const MaterialApp(title: 'Returning Data', home: HomeScreen()));\n}\n\nclass HomeScreen extends StatelessWidget {\n  const HomeScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Returning Data Demo')),\n      body: const Center(child: SelectionButton()),\n    );\n  }\n}\n\nclass SelectionButton extends StatefulWidget {\n  const SelectionButton({super.key});\n\n  @override\n  State createState() => _SelectionButtonState();\n}\n\nclass _SelectionButtonState extends State {\n  @override\n  Widget build(BuildContext context) {\n    return ElevatedButton(\n      onPressed: () {\n        _navigateAndDisplaySelection(context);\n      },\n      child: const Text('Pick an option, any option!'),\n    );\n  }\n\n  // A method that launches the SelectionScreen and awaits the result from\n  // Navigator.pop.\n  Future _navigateAndDisplaySelection(BuildContext context) async {\n    // Navigator.push returns a Future that completes after calling\n    // Navigator.pop on the Selection Screen.\n    final result = await Navigator.push(\n      context,\n      MaterialPageRoute(builder: (context) => const SelectionScreen()),\n    );\n\n    // When a BuildContext is used from a StatefulWidget, the mounted property\n    // must be checked after an asynchronous gap.\n    if (!context.mounted) return;\n\n    // After the Selection Screen returns a result, hide any previous snackbars\n    // and show the new result.\n    ScaffoldMessenger.of(context)\n      ..removeCurrentSnackBar()\n      ..showSnackBar(SnackBar(content: Text('\$result')));\n  }\n}\n\nclass SelectionScreen extends StatelessWidget {\n  const SelectionScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Pick an option')),\n      body: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Padding(\n              padding: const EdgeInsets.all(8),\n              child: ElevatedButton(\n                onPressed: () {\n                  // Close the screen and return \"Yep!\" as the result.\n                  Navigator.pop(context, 'Yep!');\n                },\n                child: const Text('Yep!'),\n              ),\n            ),\n            Padding(\n              padding: const EdgeInsets.all(8),\n              child: ElevatedButton(\n                onPressed: () {\n                  // Close the screen and return \"Nope.\" as the result.\n                  Navigator.pop(context, 'Nope.');\n                },\n                child: const Text('Nope.'),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "class HomeScreen extends StatelessWidget {\n  const HomeScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Returning Data Demo')),\n      // Create the SelectionButton widget in the next step.\n      body: const Center(child: SelectionButton()),\n    );\n  }\n}\n\nclass SelectionButton extends StatefulWidget {\n  const SelectionButton({super.key});\n\n  @override\n  State<SelectionButton> createState() => _SelectionButtonState();\n}\n\nclass _SelectionButtonState extends State<SelectionButton> {\n  @override\n  Widget build(BuildContext context) {\n    return ElevatedButton(\n      onPressed: () {\n        _navigateAndDisplaySelection(context);\n      },\n      child: const Text('Pick an option, any option!'),\n    );\n  }\n\n  Future<void> _navigateAndDisplaySelection(BuildContext context) async {\n    // Navigator.push returns a Future that completes after calling\n    // Navigator.pop on the Selection Screen.\n    final result = await Navigator.push(\n      context,\n      // Create the SelectionScreen in the next step.\n      MaterialPageRoute<String>(builder: (context) => const SelectionScreen()),\n    );\n  }\n}\n\nclass SelectionScreen extends StatelessWidget {\n  const SelectionScreen({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Pick an option')),\n      body: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            Padding(\n              padding: const EdgeInsets.all(8),\n              child: ElevatedButton(\n                onPressed: () {\n                  // Pop here with \"Yep\"...\n                },\n                child: const Text('Yep!'),\n              ),\n            ),\n            Padding(\n              padding: const EdgeInsets.all(8),\n              child: ElevatedButton(\n                onPressed: () {\n                  // Pop here with \"Nope\"...\n                },\n                child: const Text('Nope.'),\n              ),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n\nElevatedButton(\n  onPressed: () {\n    // Close the screen and return \"Yep!\" as the result.\n    Navigator.pop(context, 'Yep!');\n  },\n  child: const Text('Yep!'),\n)\n\nElevatedButton(\n  onPressed: () {\n    // Close the screen and return \"Nope.\" as the result.\n    Navigator.pop(context, 'Nope.');\n  },\n  child: const Text('Nope.'),\n)\n\n// A method that launches the SelectionScreen and awaits the result from\n// Navigator.pop.\nFuture<void> _navigateAndDisplaySelection(BuildContext context) async {\n  // Navigator.push returns a Future that completes after calling\n  // Navigator.pop on the Selection Screen.\n  final result = await Navigator.push(\n    context,\n    MaterialPageRoute<String>(builder: (context) => const SelectionScreen()),\n  );\n\n  // When a BuildContext is used from a StatefulWidget, the mounted property\n  // must be checked after an asynchronous gap.\n  if (!context.mounted) return;\n\n  // After the Selection Screen returns a result, hide any previous snackbars\n  // and show the new result.\n  ScaffoldMessenger.of(context)\n    ..removeCurrentSnackBar()\n    ..showSnackBar(SnackBar(content: Text('\$result')));\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Set Up App Links",
        body: "title: Set up app links for Android\ndescription: >-\n  Learn how to set up app links for an\n  Android application built with Flutter.\n\nDeep linking is a mechanism for launching an app with a URI.\nThis URI contains scheme, host, and path,\nand opens the app to a specific screen.\n\nAn app link is a type of deep link that uses\nhttp or https and is exclusive to Android devices.\n\nSetting up app links requires one to own a web domain.\nOtherwise, consider using [Firebase Hosting][]\nor [GitHub Pages][] as a temporary solution.\n\nOnce you've set up your deep links, you can validate them.\nTo learn more, see [Validate deep links][].\nCustomize a Flutter application\n\nWrite a Flutter app that can handle an incoming URL.\nThis example uses the [go_router][] package to handle the routing.\nThe Flutter team maintains the go_router package.\nIt provides a simple API to handle complex routing scenarios.\nTo create a new application, type flutter create :\nTo include go_router package in your app,\n    add a dependency for go_router to the project:\n\n    To add the go_router package as a dependency,\n    run flutter pub add:\nTo handle the routing,\n    create a GoRouter object in the main.dart file:\n\n    dart title=\"main.dart\"\n    import 'package:flutter/material.dart';\n    import 'package:go_router/go_router.dart';\n\n    void main() => runApp(MaterialApp.router(routerConfig: router));\n\n    /// This handles '/' and '/details'.\n    final router = GoRouter(\n      routes: [\n        GoRoute(\n          path: '/',\n          builder: (, ) => Scaffold(\n            appBar: AppBar(title: const Text('Home Screen')),\n          ),\n          routes: [\n            GoRoute(\n              path: 'details',\n              builder: (, ) => Scaffold(\n                appBar: AppBar(title: const Text('Details Screen')),\n              ),\n            ),\n          ],\n        ),\n      ],\n    );\n    xml\n\n\n\n\n\n\n\n    xml\n\n    xml\n\n    console\nkeytool -list -v -keystore\njson\n[{\n  \"relation\": [\"delegate_permission/common.handle_all_urls\"],\n  \"target\": {\n    \"namespace\": \"android_app\",\n    \"package_name\": \"com.example.deeplink_cookbook\",\n    \"sha256_cert_fingerprints\":\n    [\"FF:2A:CF:7B:DD:CC:F1:03:3E:E8:B2:27:7C:A2:E3:3C:DE:13:DB:AC:8E:EB:3A:B9:72:A1:0E:26:8A:F5:EC:AF\"]\n  }\n}]\nconsole\nadb shell 'am start -a android.intent.action.VIEW \\\n    -c android.intent.category.BROWSABLE \\\n    -d \"http:///details\"' \\\n\n\n:::note\nThis doesn't test whether the web files are\nhosted correctly,\nthe command launches the app even\nif web files are not presented.\n:::\n\nTo test both web and app setup, you must click a link\ndirectly through web browser or another app.\nOne way is to create a Google Doc, add the link, and tap on it.\n\n:::note\nIf you are debugging locally (and not downloading the app from the Play Store),\nyou might need to enable the toggle for Supported web addresses manually.\n:::\n\nIf everything is set up correctly, the Flutter application\nlaunches and displays the details screen:\n\nAppendix\n\nSource code: [deeplink_cookbook][]",
        codeSnippet: "\$ flutter create deeplink_cookbook\n    \n\n    \$ flutter pub add go_router\n    \n\n## 2. Modify AndroidManifest.xml\n\n 1. Open the Flutter project with VS Code or Android Studio.\n 2. Navigate to `android/app/src/main/AndroidManifest.xml` file.\n 3. Add the following metadata tag and intent filter inside the\n   `<activity>` tag with `.MainActivity`.\n\n    Replace `example.com` with your own web domain.\n\n    \n\n    :::version-note\n    If you use a Flutter version earlier than 3.27,\n    you need to manually opt in to deep linking by\n    adding the following metadata tag to `<activity>`:\n\n    \n\n    :::\n\n    :::note\n    If you use a third-party plugin to handle deep links,\n    such as [app_links][],\n    Flutter's default deeplink handler will\n    break these plugins.\n\n    To opt out of using Flutter's default deep link handler,\n    add the following metadata tag to `<activity>`:\n\n    \n\n    :::\n\n## 3. Hosting assetlinks.json file\n\nHost an `assetlinks.json` file in using a web server\nwith a domain that you own. This file tells the\nmobile browser which Android application to open instead\nof the browser. To create the file,\nget the package name of the Flutter app you created in\nthe previous step and the sha256 fingerprint of the\nsigning key you will be using to build the APK.\n\n### Package name\n\nLocate the package name in `AndroidManifest.xml`,\nthe `package` property under `<manifest>` tag.\nPackage names are usually in the format of `com.example.*`.\n\n### sha256 fingerprint\n\nThe process might differ depending on how the apk is signed.\n\n#### Using google play app signing\n\nYou can find the sha256 fingerprint directly from play\ndeveloper console. Open your app in the play console,\nunder **Release> Setup > App Integrity> App Signing tab**:\n\n<img src=\"/assets/images/docs/cookbook/set-up-app-links-pdc-signing-key.png\" alt=\"Screenshot of sha256 fingerprint in play developer console\" width=\"50%\" />\n\n#### Using local keystore\n\nIf you are storing the key locally,\nyou can generate sha256 using the following command:\n\n### assetlinks.json\n\nThe hosted file should look similar to this:\n\n 1. Set the `package_name` value to your Android application ID.\n\n 2. Set sha256_cert_fingerprints to the value you got\n    from the previous step.\n\n 3.  Host the file at a URL that resembles the following:\n    `<webdomain>/.well-known/assetlinks.json`\n\n 4. Verify that your browser can access this file.\n\n:::note\nIf you have multiple flavors, you can have many sha256_cert_fingerprint\nvalues in the sha256_cert_fingerprints field.\nJust add it to the sha256_cert_fingerprints list\n:::\n\n## Testing\n\nYou can use a real device or the Emulator to test an app link,\nbut first make sure you have executed `flutter run` at least once on\nthe devices. This ensures that the Flutter application is installed.\n\n<img src=\"/assets/images/docs/cookbook/set-up-app-links-emulator-installed.png\" alt=\"Emulator screenshot\" width=\"50%\" />\n\nTo test **only** the app setup, use the adb command:",
        hasImage: false,
      ),
      AppLesson(
        title: "Set Up Universal Links",
        body: "title: Set up universal links for iOS\ndescription: >-\n   Learn how to set up universal links for an\n   iOS application built with Flutter.\n\nDeep linking allows an app user to launch an app with a URI.\nThis URI contains scheme, host, and path,\nand opens the app to a specific screen.\n\nA universal link, a type of deep link exclusive to iOS devices,\nuses only the http or https protocols.\n\nTo set up universal links, you need to own a web domain.\nAs a temporary solution,\nconsider using [Firebase Hosting][] or [GitHub Pages][].\n\nOnce you've set up your deep links, you can validate them.\nTo learn more, see [Validate deep links][].\nCreate or modify a Flutter app\n\nWrite a Flutter app that can handle an incoming URL.\n\nThis example uses the [go_router][] package to handle the routing.\nThe Flutter team maintains the go_router package.\nIt provides a simple API to handle complex routing scenarios.\nTo create a new application, type flutter create .\nTo include the go_router package as a dependency,\n   run flutter pub add:\nTo handle the routing, create a GoRouter object in the main.dart file:\n\n    dart title=\"main.dart\"\n    import 'package:flutter/material.dart';\n    import 'package:go_router/go_router.dart';\n\n    void main() => runApp(MaterialApp.router(routerConfig: router));\n\n    /// This handles '/' and '/details'.\n    final router = GoRouter(\n      routes: [\n        GoRoute(\n          path: '/',\n          builder: (, ) => Scaffold(\n            appBar: AppBar(title: const Text('Home Screen')),\n          ),\n          routes: [\n            GoRoute(\n              path: 'details',\n              builder: (, ) => Scaffold(\n                appBar: AppBar(title: const Text('Details Screen')),\n              ),\n            ),\n          ],\n        ),\n      ],\n    );\n    xml\n\n\n\n\n     [!com.apple.developer.associated-domains!]\n     [!!]\n       [!applinks:example.com!]\n     [!!]\n\n\n   json\n{\n  \"applinks\": {\n    \"apps\": [],\n    \"details\": [\n      {\n        \"appIDs\": [\n          \"S8QB4VV633.com.example.deeplinkCookbook\"\n        ],\n        \"paths\": [\n          \"\"\n        ],\n        \"components\": [\n          {\n            \"/\": \"/\"\n          }\n        ]\n      }\n    ]\n  },\n  \"webcredentials\": {\n    \"apps\": [\n      \"S8QB4VV633.com.example.deeplinkCookbook\"\n    ]\n  }\n}\nconsole\n   \$ xcrun simctl openurl booted https:///details\nIf you test with a physical iOS device:\nLaunch the Note app.\nType the URL in the Note app.\nClick the resulting link.\n\n   If successful, the Flutter app launches and displays its details screen.\n\n\nFind the source code\n\nYou can find the source code for the [deeplink_cookbook][]\nrecipe in the GitHub repo.",
        codeSnippet: "\$ flutter create deeplink_cookbook\n    \n\n    \$ flutter pub add go_router\n    \n\n## Adjust iOS build settings\n\n1. Launch Xcode.\n\n1. Open the `ios/Runner.xcworkspace` file inside the\n   Flutter project's `ios` folder.\n\n   :::version-note\n   If you use a Flutter version earlier than 3.27,\n   you need to manually opt in to deep linking by adding the\n   key and value pair `FlutterDeepLinkingEnabled` and `YES` to `info.Plist`.\n   :::\n\n   :::note\n   If you're using third-party plugins to handle deep links,\n   such as [app_links][],\n   Flutter's default deeplink handler will\n   break these plugins.\n\n   If you use a third-party plugin, add the\n   key and value pair `FlutterDeepLinkingEnabled` and `NO` to `info.Plist`.\n   :::\n\n### Add associated domains\n\n:::warning\nPersonal development teams don't support the Associated Domains\ncapability. To add associated domains, choose the IDE tab.\n:::\n\n<Tabs key=\"darwin-editors\">\n<Tab name=\"Xcode\">\n\n1. Launch Xcode if necessary.\n\n1. Click the top-level **Runner**.\n\n1. In the Editor, click the **Runner** target.\n\n1. Click **Signing & Capabilities**.\n\n1. To add a new domain, click **+ Capability** under\n   **Signing & Capabilities**.\n\n1. Click **Associated Domains**.\n\n   <img\n      src=\"/assets/images/docs/cookbook/set-up-universal-links-associated-domains.png\"\n      alt=\"Xcode associated domains screenshot\"\n      width=\"100%\" />\n\n1. In the **Associated Domains** section, click **+**.\n\n1. Enter `applinks:<web domain>`. Replace `<web domain>` with your own domain name.\n\n   <img\n      src=\"/assets/images/docs/cookbook/set-up-universal-links-add-associated-domains.png\"\n      alt=\"Xcode add associated domains screenshot\"\n      width=\"100%\" />\n\n</Tab>\n<Tab name=\"Other editors\">\n\n1. Open the `ios/Runner/Runner.entitlements` XML file in your preferred editor.\n\n1. Add an associated domain inside the `<dict>` tag.\n\n   \n\n1. Save the `ios/Runner/Runner.entitlements` file.\n\nTo check that the associated domains you created are available,\nperform the following steps:\n\n1. Launch Xcode if necessary.\n\n1. Click the top-level **Runner**.\n\n1. In the Editor, click the **Runner** target.\n\n1. Click **Signing & Capabilities**.\n   The domains should appear in the\n   **Associated Domains** section.\n\n   <img\n      src=\"/assets/images/docs/cookbook/set-up-universal-links-add-associated-domains.png\"\n      alt=\"Xcode add associated domains screenshot\"\n      width=\"100%\" />\n\n</Tab>\n</Tabs>\n\nYou have finished configuring the application for deep linking.\n\n## Associate your app with your web domain\n\nYou need to host an `apple-app-site-association` file in the web domain.\nThis file tells the mobile browser which\niOS application to open instead of the browser.\nTo create the file, find the `appID` of the Flutter app you\ncreated in the previous section.\n\n### Locate components of the `appID`\n\nApple formats the `appID` as `<team id>.<bundle id>`.\n\n* Locate the bundle ID in the Xcode project.\n* Locate the team ID in the [developer account][].\n\n**For example:** Given a team ID of `S8QB4VV633`\nand a bundle ID of `com.example.deeplinkCookbook`,\nyou would enter an `appID` entry of\n`S8QB4VV633.com.example.deeplinkCookbook`.\n\n### Create and host `apple-app-site-association` JSON file\n\nThis file uses the JSON format.\nDon't include the `.json` file extension when you save this file.\nPer [Apple's documentation][apple-app-site-assoc],\nthis file should resemble the following content:\n\n1. Set one value in the `appIDs` array to\n   `<team id>.<bundle id>`.\n\n1. Set the `paths` array to `[\"*\"]`.\n   The `paths` array specifies the allowed universal links.\n   Using the asterisk, `*` redirects every path to the Flutter app.\n   If needed, change the `paths` array value to a setting more\n   appropriate to your app.\n\n1. Host the file at a URL that resembles the following structure.\n\n   `<webdomain>/.well-known/apple-app-site-association`\n\n1. Verify that your browser can access this file.\n\n:::note\nIf you have more than one scheme/flavor, you can\nadd more than one `appID` into the `appIDs` field.\n:::\n\n## Test the universal link\n\nTest a universal link using a physical iOS device or the Simulator.\n\n:::note\nIt might take up to 24 hours before Apple's [Content Delivery Network][] (CDN)\nrequests the `apple-app-site-association` (AASA) file from your web domain.\nUntil the CDN requests the file, the universal link won't work.\nTo bypass Apple's CDN, check out the [alternate mode section][].\n:::\n\n1. Before testing,\n   install the Flutter app on the iOS device or Simulator,\n   Use `flutter run` on the desired device.\n\n   <img\n       src=\"/assets/images/docs/cookbook/set-up-universal-links-simulator.png\"\n       alt=\"Simulator screenshot\"\n       width=\"50%\" />\n\n   When complete,\n   the Flutter app displays on the home screen of the\n   iOS device or Simulator.\n\n1. If you test using the Simulator, use the Xcode CLI:",
        hasImage: false,
      ),
      AppLesson(
        title: "Authenticated Requests",
        body: "title: Make authenticated requests\ndescription: How to fetch authorized data from a web service.\n\nTo fetch data from most web services, you need to provide\nauthorization. There are many ways to do this,\nbut perhaps the most common uses the Authorization HTTP header.\nAdd authorization headers\n\nThe [http][] package provides a\nconvenient way to add headers to your requests.\nAlternatively, use the [HttpHeaders][]\nclass from the dart:io library.\n\nComplete example\n\nThis example builds upon the\n[Fetching data from the internet][] recipe.",
        codeSnippet: "final response = await http.get(\n  Uri.parse('https://jsonplaceholder.typicode.com/albums/1'),\n  // Send authorization headers to the backend.\n  headers: {HttpHeaders.authorizationHeader: 'Basic your_api_token_here'},\n);\n\nimport 'dart:async';\nimport 'dart:convert';\nimport 'dart:io';\n\nimport 'package:http/http.dart' as http;\n\nFuture<Album> fetchAlbum() async {\n  final response = await http.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/1'),\n    // Send authorization headers to the backend.\n    headers: {HttpHeaders.authorizationHeader: 'Basic your_api_token_here'},\n  );\n  final responseJson = jsonDecode(response.body) as Map<String, dynamic>;\n\n  return Album.fromJson(responseJson);\n}\n\nclass Album {\n  final int userId;\n  final int id;\n  final String title;\n\n  const Album({required this.userId, required this.id, required this.title});\n\n  factory Album.fromJson(Map<String, dynamic> json) {\n    return switch (json) {\n      {'userId': int userId, 'id': int id, 'title': String title} => Album(\n        userId: userId,\n        id: id,\n        title: title,\n      ),\n      _ => throw const FormatException('Failed to load album.'),\n    };\n  }\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Background Parsing",
        body: "title: Parse JSON in the background\ndescription: How to perform a task in the background.\n\nBy default, Dart apps do all of their work on a single thread.\nIn many cases, this model simplifies coding and is fast enough\nthat it does not result in poor app performance or stuttering animations,\noften called \"jank.\"\n\nHowever, you might need to perform an expensive computation,\nsuch as parsing a very large JSON document.\nIf this work takes more than 16 milliseconds,\nyour users experience jank.\n\nTo avoid jank, you need to perform expensive computations\nlike this in the background, using a separate [Isolate][].\nThis recipe uses the following steps:\nAdd the http package.\nMake a network request using the http package.\nConvert the response into a list of photos.\nMove this work to a separate isolate.\nAdd the http package\n\nFirst, add the [http][] package to your project.\nThe http package makes it easier to perform network\nrequests, such as fetching data from a JSON endpoint.\n\nTo add the http package as a dependency,\nrun flutter pub add:\nMake a network request\n\nThis example covers how to fetch a large JSON document\nthat contains a list of 5000 photo objects from the\n[JSONPlaceholder REST API][],\nusing the [http.get()][] method.\n\n:::note\nYou're providing an http.Client to the function in this example.\nThis makes the function easier to test and use in different environments.\n:::\nParse and convert the JSON into a list of photos\n\nNext, following the guidance from the\n[Fetch data from the internet][] recipe,\nconvert the http.Response into a list of Dart objects.\nThis makes the data easier to work with.\nCreate a Photo class\n\nFirst, create a Photo class that contains data about a photo.\nInclude a fromJson() factory method to make it easy to create a\nPhoto starting with a JSON object.\n\nConvert the response into a list of photos\n\nNow, use the following instructions to update the\nfetchPhotos() function so that it returns a\nFuture>:\nCreate a parsePhotos() function that converts the response\n     body into a List.\nUse the parsePhotos() function in the fetchPhotos() function.\n\nMove this work to a separate isolate\n\nIf you run the fetchPhotos() function on a slower device,\nyou might notice the app freezes for a brief moment as it parses and\nconverts the JSON. This is jank, and you want to get rid of it.\n\nYou can remove the jank by moving the parsing and conversion\nto a background isolate using the [compute()][]\nfunction provided by Flutter. The compute() function runs expensive\nfunctions in a background isolate and returns the result. In this case,\nrun the parsePhotos() function in the background.\n\nNotes on working with isolates\n\nIsolates communicate by passing messages back and forth. These messages can\nbe primitive values, such as null, num, bool, double, or String, or\nsimple objects such as the List in this example.\n\nYou might experience errors if you try to pass more complex objects,\nsuch as a Future or http.Response between isolates.\n\nAs an alternate solution, check out the [worker_manager][] or\n[workmanager][] packages for background processing.\nComplete example\n\n{:.site-mobile-screenshot}",
        codeSnippet: "\$ flutter pub add http\n\nFuture<http.Response> fetchPhotos(http.Client client) async {\n  return client.get(Uri.parse('https://jsonplaceholder.typicode.com/photos'));\n}\n\nclass Photo {\n  final int albumId;\n  final int id;\n  final String title;\n  final String url;\n  final String thumbnailUrl;\n\n  const Photo({\n    required this.albumId,\n    required this.id,\n    required this.title,\n    required this.url,\n    required this.thumbnailUrl,\n  });\n\n  factory Photo.fromJson(Map<String, dynamic> json) {\n    return Photo(\n      albumId: json['albumId'] as int,\n      id: json['id'] as int,\n      title: json['title'] as String,\n      url: json['url'] as String,\n      thumbnailUrl: json['thumbnailUrl'] as String,\n    );\n  }\n}\n\n// A function that converts a response body into a List<Photo>.\nList<Photo> parsePhotos(String responseBody) {\n  final parsed = (jsonDecode(responseBody) as List<Object?>)\n      .cast<Map<String, Object?>>();\n\n  return parsed.map<Photo>(Photo.fromJson).toList();\n}\n\nFuture<List<Photo>> fetchPhotos(http.Client client) async {\n  final response = await client.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/photos'),\n  );\n\n  // Synchronously run parsePhotos in the main isolate.\n  return parsePhotos(response.body);\n}\n\nFuture<List<Photo>> fetchPhotos(http.Client client) async {\n  final response = await client.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/photos'),\n  );\n\n  // Use the compute function to run parsePhotos in a separate isolate.\n  return compute(parsePhotos, response.body);\n}\n\nimport 'dart:async';\nimport 'dart:convert';\n\nimport 'package:flutter/foundation.dart';\nimport 'package:flutter/material.dart';\nimport 'package:http/http.dart' as http;\n\nFuture<List<Photo>> fetchPhotos(http.Client client) async {\n  final response = await client.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/photos'),\n  );\n\n  // Use the compute function to run parsePhotos in a separate isolate.\n  return compute(parsePhotos, response.body);\n}\n\n// A function that converts a response body into a List<Photo>.\nList<Photo> parsePhotos(String responseBody) {\n  final parsed = (jsonDecode(responseBody) as List<Object?>)\n      .cast<Map<String, Object?>>();\n\n  return parsed.map<Photo>(Photo.fromJson).toList();\n}\n\nclass Photo {\n  final int albumId;\n  final int id;\n  final String title;\n  final String url;\n  final String thumbnailUrl;\n\n  const Photo({\n    required this.albumId,\n    required this.id,\n    required this.title,\n    required this.url,\n    required this.thumbnailUrl,\n  });\n\n  factory Photo.fromJson(Map<String, dynamic> json) {\n    return Photo(\n      albumId: json['albumId'] as int,\n      id: json['id'] as int,\n      title: json['title'] as String,\n      url: json['url'] as String,\n      thumbnailUrl: json['thumbnailUrl'] as String,\n    );\n  }\n}\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const appTitle = 'Isolate Demo';\n\n    return const MaterialApp(\n      title: appTitle,\n      home: MyHomePage(title: appTitle),\n    );\n  }\n}\n\nclass MyHomePage extends StatefulWidget {\n  const MyHomePage({super.key, required this.title});\n\n  final String title;\n\n  @override\n  State<MyHomePage> createState() => _MyHomePageState();\n}\n\nclass _MyHomePageState extends State<MyHomePage> {\n  late Future<List<Photo>> futurePhotos;\n\n  @override\n  void initState() {\n    super.initState();\n    futurePhotos = fetchPhotos(http.Client());\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: Text(widget.title)),\n      body: FutureBuilder<List<Photo>>(\n        future: futurePhotos,\n        builder: (context, snapshot) {\n          if (snapshot.hasError) {\n            return const Center(child: Text('An error has occurred!'));\n          } else if (snapshot.hasData) {\n            return PhotosList(photos: snapshot.data!);\n          } else {\n            return const Center(child: CircularProgressIndicator());\n          }\n        },\n      ),\n    );\n  }\n}\n\nclass PhotosList extends StatelessWidget {\n  const PhotosList({super.key, required this.photos});\n\n  final List<Photo> photos;\n\n  @override\n  Widget build(BuildContext context) {\n    return GridView.builder(\n      gridDelegate: const SliverGridDelegateWithFixedCrossAxisCount(\n        crossAxisCount: 2,\n      ),\n      itemCount: photos.length,\n      itemBuilder: (context, index) {\n        return Image.network(photos[index].thumbnailUrl);\n      },\n    );\n  }\n}",
        hasImage: true,
      ),
      AppLesson(
        title: "Delete Data",
        body: "title: Delete data on the internet\ndescription: How to use the http package to delete data on the internet.\n\nThis recipe covers how to delete data over\nthe internet using the http package.\n\nThis recipe uses the following steps:\nAdd the http package.\nDelete data on the server.\nUpdate the screen.\nAdd the http package\n\nTo add the http package as a dependency,\nrun flutter pub add:\n\nImport the http package.\n\n{% render \"docs/cookbook/networking/internet-permission.md\" %}\nDelete data on the server\n\nThis recipe covers how to delete an album from the\n[JSONPlaceholder][] using the http.delete() method.\nNote that this requires the id of the album that\nyou want to delete. For this example,\nuse something you already know, for example id = 1.\n\nThe http.delete() method returns a Future that contains a Response.\n\n [Future][] is a core Dart class for working with\n  async operations. A Future object represents a potential\n  value or error that will be available at some time in the future.\n The http.Response class contains the data received from a successful\n  http call.\nThe deleteAlbum() method takes an id argument that\n  is needed to identify the data to be deleted from the server.\nUpdate the screen\n\nIn order to check whether the data has been deleted or not,\nfirst fetch the data from the [JSONPlaceholder][]\nusing the http.get() method, and display it in the screen.\n(See the [Fetch Data][] recipe for a complete example.)\nYou should now have a Delete Data button that,\nwhen pressed, calls the deleteAlbum() method.\n\nNow, when you click on the Delete Data button,\nthe deleteAlbum() method is called and the id\nyou are passing is the id of the data that you retrieved\nfrom the internet. This means you are going to delete\nthe same data that you fetched from the internet.\nReturning a response from the deleteAlbum() method\nOnce the delete request has been made,\nyou can return a response from the deleteAlbum()\nmethod to notify our screen that the data has been deleted.\n\nFutureBuilder() now rebuilds when it receives a response.\nSince the response won't have any data in its body\nif the request was successful,\nthe Album.fromJson() method creates an instance of the\nAlbum object with a default value (null in our case).\nThis behavior can be altered in any way you wish.\n\nThat's all!\nNow you've got a function that deletes the data from the internet.\nComplete example",
        codeSnippet: "\$ flutter pub add http\n\nimport 'package:http/http.dart' as http;\n\nFuture<http.Response> deleteAlbum(String id) async {\n  final http.Response response = await http.delete(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/\$id'),\n    headers: <String, String>{\n      'Content-Type': 'application/json; charset=UTF-8',\n    },\n  );\n\n  return response;\n}\n\nColumn(\n  mainAxisAlignment: MainAxisAlignment.center,\n  children: <Widget>[\n    Text(snapshot.data?.title ?? 'Deleted'),\n    ElevatedButton(\n      child: const Text('Delete Data'),\n      onPressed: () {\n        setState(() {\n          _futureAlbum = deleteAlbum(\n            snapshot.data!.id.toString(),\n          );\n        });\n      },\n    ),\n  ],\n);\n\nFuture<Album> deleteAlbum(String id) async {\n  final http.Response response = await http.delete(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/\$id'),\n    headers: <String, String>{\n      'Content-Type': 'application/json; charset=UTF-8',\n    },\n  );\n\n  if (response.statusCode == 200) {\n    // If the server did return a 200 OK response,\n    // then return an empty Album. After deleting,\n    // you'll get an empty JSON `{}` response.\n    // Don't return `null`, otherwise `snapshot.hasData`\n    // will always return false on `FutureBuilder`.\n    return Album.empty();\n  } else {\n    // If the server did not return a \"200 OK response\",\n    // then throw an exception.\n    throw Exception('Failed to delete album.');\n  }\n}\n\nimport 'dart:async';\nimport 'dart:convert';\n\nimport 'package:flutter/material.dart';\nimport 'package:http/http.dart' as http;\n\nFuture<Album> fetchAlbum() async {\n  final response = await http.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/1'),\n  );\n\n  if (response.statusCode == 200) {\n    // If the server did return a 200 OK response, then parse the JSON.\n    return Album.fromJson(jsonDecode(response.body) as Map<String, dynamic>);\n  } else {\n    // If the server did not return a 200 OK response, then throw an exception.\n    throw Exception('Failed to load album');\n  }\n}\n\nFuture<Album> deleteAlbum(String id) async {\n  final http.Response response = await http.delete(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/\$id'),\n    headers: <String, String>{\n      'Content-Type': 'application/json; charset=UTF-8',\n    },\n  );\n\n  if (response.statusCode == 200) {\n    // If the server did return a 200 OK response,\n    // then return an empty Album. After deleting,\n    // you'll get an empty JSON `{}` response.\n    // Don't return `null`, otherwise `snapshot.hasData`\n    // will always return false on `FutureBuilder`.\n    return Album.empty();\n  } else {\n    // If the server did not return a \"200 OK response\",\n    // then throw an exception.\n    throw Exception('Failed to delete album.');\n  }\n}\n\nclass Album {\n  int? id;\n  String? title;\n\n  Album({this.id, this.title});\n\n  Album.empty();\n\n  factory Album.fromJson(Map<String, dynamic> json) {\n    return switch (json) {\n      {'id': int id, 'title': String title} => Album(id: id, title: title),\n      _ => throw const FormatException('Failed to load album.'),\n    };\n  }\n}\n\nvoid main() {\n  runApp(const MyApp());\n}\n\nclass MyApp extends StatefulWidget {\n  const MyApp({super.key});\n\n  @override\n  State<MyApp> createState() {\n    return _MyAppState();\n  }\n}\n\nclass _MyAppState extends State<MyApp> {\n  late Future<Album> _futureAlbum;\n\n  @override\n  void initState() {\n    super.initState();\n    _futureAlbum = fetchAlbum();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: 'Delete Data Example',\n      theme: ThemeData(\n        colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple),\n      ),\n      home: Scaffold(\n        appBar: AppBar(title: const Text('Delete Data Example')),\n        body: Center(\n          child: FutureBuilder<Album>(\n            future: _futureAlbum,\n            builder: (context, snapshot) {\n              // If the connection is done,\n              // check for response data or an error.\n              if (snapshot.connectionState == ConnectionState.done) {\n                if (snapshot.hasData) {\n                  return Column(\n                    mainAxisAlignment: MainAxisAlignment.center,\n                    children: <Widget>[\n                      Text(snapshot.data?.title ?? 'Deleted'),\n                      ElevatedButton(\n                        child: const Text('Delete Data'),\n                        onPressed: () {\n                          setState(() {\n                            _futureAlbum = deleteAlbum(\n                              snapshot.data!.id.toString(),\n                            );\n                          });\n                        },\n                      ),\n                    ],\n                  );\n                } else if (snapshot.hasError) {\n                  return Text('\${snapshot.error}');\n                }\n              }\n\n              // By default, show a loading spinner.\n              return const CircularProgressIndicator();\n            },\n          ),\n        ),\n      ),\n    );\n  }\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Fetch Data",
        body: "title: Fetch data from the internet\ndescription: How to fetch data over the internet using the http package.\n\nFetching data from the internet is necessary for most apps.\nLuckily, Dart and Flutter provide tools, such as the\nhttp package, for this type of work.\n\n:::note\nYou should avoid directly using dart:io or dart:html\nto make HTTP requests.\nThose libraries are platform-dependent\nand tied to a single implementation.\n:::\n\nThis recipe uses the following steps:\nAdd the http package.\nMake a network request using the http package.\nConvert the response into a custom Dart object.\nFetch and display the data with Flutter.\nAdd the http package\n\nThe [http][] package provides the\nsimplest way to fetch data from the internet.\n\nTo add the http package as a dependency,\nrun flutter pub add:\n\nImport the http package.\n\n{% render \"docs/cookbook/networking/internet-permission.md\" %}\nMake a network request\n\nThis recipe covers how to fetch a sample album from the\n[JSONPlaceholder][] using the [http.get()][] method.\n\nThe http.get() method returns a Future that contains a Response.\n\n [Future][] is a core Dart class for working with\n  async operations. A Future object represents a potential\n  value or error that will be available at some time in the future.\n The http.Response class contains the data received from a successful\n  http call.\nConvert the response into a custom Dart object\n\nWhile it's easy to make a network request, working with a raw\nFuture isn't very convenient.\nTo make your life easier,\nconvert the http.Response into a Dart object.\nCreate an Album class\n\nFirst, create an Album class that contains the data from the\nnetwork request. It includes a factory constructor that\ncreates an Album from JSON.\n\nConverting JSON using [pattern matching][] is only one option.\nFor more information, see the full article on\n[JSON and serialization][].\n\nConvert the http.Response to an Album\n\nNow, use the following steps to update the fetchAlbum()\nfunction to return a Future:\nConvert the response body into a JSON Map with\n     the dart:convert package.\nIf the server does return an OK response with a status code of\n     200, then convert the JSON Map into an Album\n     using the fromJson() factory method.\nIf the server does not return an OK response with a status code of 200,\n     then throw an exception.\n     (Even in the case of a \"404 Not Found\" server response,\n     throw an exception. Do not return null.\n     This is important when examining\n     the data in snapshot, as shown below.)\n\nHooray!\nNow you've got a function that fetches an album from the internet.\nFetch the data\n\nCall the fetchAlbum() method in either the\n[initState()][] or [didChangeDependencies()][]\nmethods.\n\nThe initState() method is called exactly once and then never again.\nIf you want to have the option of reloading the API in response to an\n[InheritedWidget][] changing, put the call into the\ndidChangeDependencies() method.\nSee [State][] for more details.\n\nThis Future is used in the next step.\nDisplay the data\n\nTo display the data on screen, use the\n[FutureBuilder][] widget.\nThe FutureBuilder widget comes with Flutter and\nmakes it easy to work with asynchronous data sources.\n\nYou must provide two parameters:\nThe Future you want to work with.\n     In this case, the future returned from\n     the fetchAlbum() function.\nA builder function that tells Flutter\n     what to render, depending on the\n     state of the Future: loading, success, or error.\n\nNote that snapshot.hasData only returns true\nwhen the snapshot contains a non-null data value.\n\nBecause fetchAlbum can only return non-null values,\nthe function should throw an exception\neven in the case of a \"404 Not Found\" server response.\nThrowing an exception sets the snapshot.hasError to true\nwhich can be used to display an error message.\n\nOtherwise, the spinner will be displayed.\n\nWhy is fetchAlbum() called in initState()?\n\nAlthough it's convenient,\nit's not recommended to put an API call in a build() method.\n\nFlutter calls the build() method every time it needs\nto change anything in the view,\nand this happens surprisingly often.\nThe fetchAlbum() method, if placed inside build(), is repeatedly\ncalled on each rebuild causing the app to slow down.\n\nStoring the fetchAlbum() result in a state variable ensures that\nthe Future is executed only once and then cached for subsequent\nrebuilds.\nTesting\n\nFor information on how to test this functionality,\nsee the following recipes:\n\n   [Introduction to unit testing][]\n   [Mock dependencies using Mockito][]\nComplete example",
        codeSnippet: "\$ flutter pub add http\n\nimport 'package:http/http.dart' as http;\n\nFuture<http.Response> fetchAlbum() {\n  return http.get(Uri.parse('https://jsonplaceholder.typicode.com/albums/1'));\n}\n\nclass Album {\n  final int userId;\n  final int id;\n  final String title;\n\n  const Album({required this.userId, required this.id, required this.title});\n\n  factory Album.fromJson(Map<String, dynamic> json) {\n    return switch (json) {\n      {'userId': int userId, 'id': int id, 'title': String title} => Album(\n        userId: userId,\n        id: id,\n        title: title,\n      ),\n      _ => throw const FormatException('Failed to load album.'),\n    };\n  }\n}\n\nFuture<Album> fetchAlbum() async {\n  final response = await http.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/1'),\n    headers: {'Accept': 'application/json'},\n  );\n\n  if (response.statusCode == 200) {\n    // If the server did return a 200 OK response,\n    // then parse the JSON.\n    return Album.fromJson(jsonDecode(response.body) as Map<String, dynamic>);\n  } else {\n    // If the server did not return a 200 OK response,\n    // then throw an exception.\n    throw Exception('Failed to load album');\n  }\n}\n\nclass _MyAppState extends State<MyApp> {\n  late Future<Album> futureAlbum;\n\n  @override\n  void initState() {\n    super.initState();\n    futureAlbum = fetchAlbum();\n  }\n  // ···\n}\n\nFutureBuilder<Album>(\n  future: futureAlbum,\n  builder: (context, snapshot) {\n    if (snapshot.hasData) {\n      return Text(snapshot.data!.title);\n    } else if (snapshot.hasError) {\n      return Text('\${snapshot.error}');\n    }\n\n    // By default, show a loading spinner.\n    return const CircularProgressIndicator();\n  },\n)\n\nimport 'dart:async';\nimport 'dart:convert';\n\nimport 'package:flutter/material.dart';\nimport 'package:http/http.dart' as http;\n\nFuture<Album> fetchAlbum() async {\n  final response = await http.get(\n    Uri.parse('https://jsonplaceholder.typicode.com/albums/1'),\n    headers: {'Accept': 'application/json'},\n  );\n\n  if (response.statusCode == 200) {\n    // If the server did return a 200 OK response,\n    // then parse the JSON.\n    return Album.fromJson(jsonDecode(response.body) as Map<String, dynamic>);\n  } else {\n    // If the server did not return a 200 OK response,\n    // then throw an exception.\n    throw Exception('Failed to load album');\n  }\n}\n\nclass Album {\n  final int userId;\n  final int id;\n  final String title;\n\n  const Album({required this.userId, required this.id, required this.title});\n\n  factory Album.fromJson(Map<String, dynamic> json) {\n    return switch (json) {\n      {'userId': int userId, 'id': int id, 'title': String title} => Album(\n        userId: userId,\n        id: id,\n        title: title,\n      ),\n      _ => throw const FormatException('Failed to load album.'),\n    };\n  }\n}\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatefulWidget {\n  const MyApp({super.key});\n\n  @override\n  State<MyApp> createState() => _MyAppState();\n}\n\nclass _MyAppState extends State<MyApp> {\n  late Future<Album> futureAlbum;\n\n  @override\n  void initState() {\n    super.initState();\n    futureAlbum = fetchAlbum();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return MaterialApp(\n      title: 'Fetch Data Example',\n      theme: ThemeData(\n        colorScheme: ColorScheme.fromSeed(seedColor: Colors.deepPurple),\n      ),\n      home: Scaffold(\n        appBar: AppBar(title: const Text('Fetch Data Example')),\n        body: Center(\n          child: FutureBuilder<Album>(\n            future: futureAlbum,\n            builder: (context, snapshot) {\n              if (snapshot.hasData) {\n                return Text(snapshot.data!.title);\n              } else if (snapshot.hasError) {\n                return Text('\${snapshot.error}');\n              }\n\n              // By default, show a loading spinner.\n              return const CircularProgressIndicator();\n            },\n          ),\n        ),\n      ),\n    );\n  }\n\n}",
        hasImage: false,
      ),
