      AppLesson(
        title: "Web Sockets",
        body: "title: Communicate with WebSockets\ndescription: How to connect to a web socket.\n\nIn addition to normal HTTP requests,\nyou can connect to servers using WebSockets.\nWebSockets allow for two-way communication with a server\nwithout polling.\n\nIn this example, connect to a [test WebSocket server][].\nThe server sends back the same message you send to it.\nThis recipe uses the following steps:\nConnect to a WebSocket server.\nListen for messages from the server.\nSend data to the server.\nClose the WebSocket connection.\nConnect to a WebSocket server\n\nThe [web_socket_channel][] package provides the\ntools you need to connect to a WebSocket server.\n\nThe package provides a WebSocketChannel\nthat allows you to both listen for messages\nfrom the server and push messages to the server.\n\nIn Flutter, use the following line to\ncreate a WebSocketChannel that connects to a server:\n\nListen for messages from the server\n\nNow that you've established a connection,\nlisten to messages from the server.\n\nAfter sending a message to the test server,\nit sends the same message back.\n\nIn this example, use a [StreamBuilder][]\nwidget to listen for new messages, and a\n[Text][] widget to display them.\n\nHow this works\n\nThe WebSocketChannel provides a\n[Stream][] of messages from the server.\n\nThe Stream class is a fundamental part of the dart:async package.\nIt provides a way to listen to async events from a data source.\nUnlike Future, which returns a single async response,\nthe Stream class can deliver many events over time.\n\nThe [StreamBuilder][] widget connects to a Stream\nand asks Flutter to rebuild every time it\nreceives an event using the given builder() function.\nSend data to the server\n\nTo send data to the server,\nadd() messages to the sink provided\nby the WebSocketChannel.\n\nHow this works\n\nThe WebSocketChannel provides a\n[StreamSink][] to push messages to the server.\n\nThe StreamSink class provides a general way to add sync or async\nevents to a data source.\nClose the WebSocket connection\n\nAfter you're done using the WebSocket, close the connection:\n\nComplete example\n\n{:.site-mobile-screenshot}",
        codeSnippet: "final WebSocketChannel channel = WebSocketChannel.connect(\n  Uri.parse('wss://echo.websocket.org'),\n);\n\nStreamBuilder(\n  stream: channel.stream,\n  builder: (context, snapshot) {\n    return Text(snapshot.hasData ? '\${snapshot.data}' : '');\n  },\n),\n\nchannel.sink.add('Hello!');\n\nchannel.sink.close();\n\nimport 'package:flutter/material.dart';\nimport 'package:web_socket_channel/web_socket_channel.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    const title = 'WebSocket Demo';\n    return const MaterialApp(\n      title: title,\n      home: MyHomePage(title: title),\n    );\n  }\n}\n\nclass MyHomePage extends StatefulWidget {\n  const MyHomePage({super.key, required this.title});\n\n  final String title;\n\n  @override\n  State<MyHomePage> createState() => _MyHomePageState();\n}\n\nclass _MyHomePageState extends State<MyHomePage> {\n  final TextEditingController _controller = TextEditingController();\n  final WebSocketChannel _channel = WebSocketChannel.connect(\n    Uri.parse('wss://echo.websocket.org'),\n  );\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: Text(widget.title)),\n      body: Padding(\n        padding: const EdgeInsets.all(20),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            Form(\n              child: TextFormField(\n                controller: _controller,\n                decoration: const InputDecoration(labelText: 'Send a message'),\n              ),\n            ),\n            const SizedBox(height: 24),\n            StreamBuilder(\n              stream: _channel.stream,\n              builder: (context, snapshot) {\n                return Text(snapshot.hasData ? '\${snapshot.data}' : '');\n              },\n            ),\n          ],\n        ),\n      ),\n      floatingActionButton: FloatingActionButton(\n        onPressed: _sendMessage,\n        tooltip: 'Send message',\n        child: const Icon(Icons.send),\n      ), // This trailing comma makes auto-formatting nicer for build methods.\n    );\n  }\n\n  void _sendMessage() {\n    if (_controller.text.isNotEmpty) {\n      _channel.sink.add(_controller.text);\n    }\n  }\n\n  @override\n  void dispose() {\n    _channel.sink.close();\n    _controller.dispose();\n    super.dispose();\n  }\n}",
        hasImage: true,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter persistence cookbook\nshortTitle: Persistence\ndescription: A catalog of recipes for adding persistence to your Flutter app.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Key Value",
        body: "title: Store key-value data on disk\ndescription: >-\n  Learn how to use the shared_preferences package to store key-value data.\n\nIf you have a relatively small collection of key-values\nto save, you can use the [shared_preferences][] plugin.\n\nNormally, you would have to\nwrite native platform integrations for storing data on each platform.\nFortunately, the [shared_preferences][] plugin can be used to\npersist key-value data to disk on each platform Flutter supports.\n\nThis recipe uses the following steps:\nAdd the dependency.\nSave data.\nRead data.\nRemove data.\n\n:::note\nTo learn more, watch this short Package of the Week video\non the shared_preferences package:\n\n:::\nAdd the dependency\n\nBefore starting, add the [shared_preferences][] package as a dependency.\n\nTo add the shared_preferences package as a dependency,\nrun flutter pub add:\nSave data\n\nTo persist data, use the setter methods provided by the\nSharedPreferences class. Setter methods are available for\nvarious primitive types, such as setInt, setBool, and setString.\n\nSetter methods do two things: First, synchronously update the\nkey-value pair in memory. Then, persist the data to disk.\n\nRead data\n\nTo read data, use the appropriate getter method provided by the\nSharedPreferences class. For each setter there is a corresponding getter.\nFor example, you can use the getInt, getBool, and getString methods.\n\nNote that the getter methods throw an exception if the persisted value\nhas a different type than the getter method expects.\nRemove data\n\nTo delete data, use the remove() method.\n\nSupported types\n\nAlthough the key-value storage provided by shared_preferences is\neasy and convenient to use, it has limitations:\n\n Only primitive types can be used: int, double, bool, String,\n  and List.\n It's not designed to store large amounts of data.\nThere is no guarantee that data will be persisted across app restarts.\nTesting support\n\nIt's a good idea to test code that persists data using shared_preferences.\nTo enable this, the package provides an\nin-memory mock implementation of the preference store.\n\nTo set up your tests to use the mock implementation,\ncall the setMockInitialValues static method in\na setUpAll() method in your test files.\nPass in a map of key-value pairs to use as the initial values.\n\nComplete example",
        codeSnippet: "flutter pub add shared_preferences\n\n// Load and obtain the shared preferences for this app.\nfinal prefs = await SharedPreferences.getInstance();\n\n// Save the counter value to persistent storage under the 'counter' key.\nawait prefs.setInt('counter', counter);\n\nfinal prefs = await SharedPreferences.getInstance();\n\n// Try reading the counter value from persistent storage.\n// If not present, null is returned, so default to 0.\nfinal counter = prefs.getInt('counter') ?? 0;\n\nfinal prefs = await SharedPreferences.getInstance();\n\n// Remove the counter key-value pair from persistent storage.\nawait prefs.remove('counter');\n\nSharedPreferences.setMockInitialValues(<String, Object>{'counter': 2});\n\nimport 'package:flutter/material.dart';\nimport 'package:shared_preferences/shared_preferences.dart';\n\nvoid main() => runApp(const MyApp());\n\nclass MyApp extends StatelessWidget {\n  const MyApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const MaterialApp(\n      title: 'Shared preferences demo',\n      home: MyHomePage(title: 'Shared preferences demo'),\n    );\n  }\n}\n\nclass MyHomePage extends StatefulWidget {\n  const MyHomePage({super.key, required this.title});\n\n  final String title;\n\n  @override\n  State<MyHomePage> createState() => _MyHomePageState();\n}\n\nclass _MyHomePageState extends State<MyHomePage> {\n  int _counter = 0;\n\n  @override\n  void initState() {\n    super.initState();\n    _loadCounter();\n  }\n\n  /// Load the initial counter value from persistent storage on start,\n  /// or fallback to 0 if it doesn't exist.\n  Future<void> _loadCounter() async {\n    final prefs = await SharedPreferences.getInstance();\n    setState(() {\n      _counter = prefs.getInt('counter') ?? 0;\n    });\n  }\n\n  /// After a click, increment the counter state and\n  /// asynchronously save it to persistent storage.\n  Future<void> _incrementCounter() async {\n    final prefs = await SharedPreferences.getInstance();\n    setState(() {\n      _counter = (prefs.getInt('counter') ?? 0) + 1;\n      prefs.setInt('counter', _counter);\n    });\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: Text(widget.title)),\n      body: Center(\n        child: Column(\n          mainAxisAlignment: MainAxisAlignment.center,\n          children: [\n            const Text('You have pushed the button this many times: '),\n            Text(\n              '\$_counter',\n              style: Theme.of(context).textTheme.headlineMedium,\n            ),\n          ],\n        ),\n      ),\n      floatingActionButton: FloatingActionButton(\n        onPressed: _incrementCounter,\n        tooltip: 'Increment',\n        child: const Icon(Icons.add),\n      ),\n    );\n  }\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Reading Writing Files",
        body: "title: Read and write files\ndescription: How to read from and write to files on disk.\n\nIn some cases, you need to read and write files to disk.\nFor example, you might need to persist data across app launches,\nor download data from the internet and save it for later offline use.\n\nTo save files to disk on mobile or desktop apps,\ncombine the [path_provider][] plugin with the [dart:io][] library.\n\nThis recipe uses the following steps:\nFind the correct local path.\nCreate a reference to the file location.\nWrite data to the file.\nRead data from the file.\n\nTo learn more, watch this Package of the Week video\non the path_provider package:\n\n:::note\nThis recipe doesn't work with web apps at this time.\nTo follow the discussion on this issue,\ncheck out flutter/flutter issue #45296.\n:::\nFind the correct local path\n\nThis example displays a counter. When the counter changes,\nwrite data on disk so you can read it again when the app loads.\nWhere should you store this data?\n\nThe [path_provider][] package\nprovides a platform-agnostic way to access commonly used locations on the\ndevice's file system. The plugin currently supports access to\ntwo file system locations:\n\nTemporary directory\n: A temporary directory (cache) that the system can\n  clear at any time. On iOS, this corresponds to the\n  [NSCachesDirectory][]. On Android, this is the value that\n  [getCacheDir()][] returns.\n\nDocuments directory\n: A directory for the app to store files that only\n  it can access. The system clears the directory only when the app\n  is deleted.\n  On iOS, this corresponds to the NSDocumentDirectory.\n  On Android, this is the AppData directory.\n\nThis example stores information in the documents directory.\nYou can find the path to the documents directory as follows:\n\nCreate a reference to the file location\n\nOnce you know where to store the file, create a reference to the\nfile's full location. You can use the [File][]\nclass from the [dart:io][] library to achieve this.\n\nWrite data to the file\n\nNow that you have a File to work with,\nuse it to read and write data.\nFirst, write some data to the file.\nThe counter is an integer, but is written to the\nfile as a string using the '\$counter' syntax.\n\nRead data from the file\n\nNow that you have some data on disk, you can read it.\nOnce again, use the File class.\n\nComplete example",
        codeSnippet: "import 'package:path_provider/path_provider.dart';\n\n  // ···\n  Future<String> get _localPath async {\n    final directory = await getApplicationDocumentsDirectory();\n\n    return directory.path;\n  }\n\nFuture<File> get _localFile async {\n  final path = await _localPath;\n  return File('\$path/counter.txt');\n}\n\nFuture<File> writeCounter(int counter) async {\n  final file = await _localFile;\n\n  // Write the file\n  return file.writeAsString('\$counter');\n}\n\nFuture<int> readCounter() async {\n  try {\n    final file = await _localFile;\n\n    // Read the file\n    final contents = await file.readAsString();\n\n    return int.parse(contents);\n  } catch (e) {\n    // If encountering an error, return 0\n    return 0;\n  }\n}\n\nimport 'dart:async';\nimport 'dart:io';\n\nimport 'package:flutter/material.dart';\nimport 'package:path_provider/path_provider.dart';\n\nvoid main() {\n  runApp(\n    MaterialApp(\n      title: 'Reading and Writing Files',\n      home: FlutterDemo(storage: CounterStorage()),\n    ),\n  );\n}\n\nclass CounterStorage {\n  Future<String> get _localPath async {\n    final directory = await getApplicationDocumentsDirectory();\n\n    return directory.path;\n  }\n\n  Future<File> get _localFile async {\n    final path = await _localPath;\n    return File('\$path/counter.txt');\n  }\n\n  Future<int> readCounter() async {\n    try {\n      final file = await _localFile;\n\n      // Read the file\n      final contents = await file.readAsString();\n\n      return int.parse(contents);\n    } catch (e) {\n      // If encountering an error, return 0\n      return 0;\n    }\n  }\n\n  Future<File> writeCounter(int counter) async {\n    final file = await _localFile;\n\n    // Write the file\n    return file.writeAsString('\$counter');\n  }\n}\n\nclass FlutterDemo extends StatefulWidget {\n  const FlutterDemo({super.key, required this.storage});\n\n  final CounterStorage storage;\n\n  @override\n  State<FlutterDemo> createState() => _FlutterDemoState();\n}\n\nclass _FlutterDemoState extends State<FlutterDemo> {\n  int _counter = 0;\n\n  @override\n  void initState() {\n    super.initState();\n    widget.storage.readCounter().then((value) {\n      setState(() {\n        _counter = value;\n      });\n    });\n  }\n\n  Future<File> _incrementCounter() {\n    setState(() {\n      _counter++;\n    });\n\n    // Write the variable as a string to the file.\n    return widget.storage.writeCounter(_counter);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Reading and Writing Files')),\n      body: Center(\n        child: Text('Button tapped \$_counter time\${_counter == 1 ? '' : 's'}.'),\n      ),\n      floatingActionButton: FloatingActionButton(\n        onPressed: _incrementCounter,\n        tooltip: 'Increment',\n        child: const Icon(Icons.add),\n      ),\n    );\n  }\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Sqlite",
        body: "title: Persist data with SQLite\ndescription: How to use SQLite to store and retrieve data.\n\n:::note\nThis guide uses the [sqflite package][].\nThis package only supports apps that run on\nmacOS, iOS, or Android.\n:::\n\nIf you are writing an app that needs to persist and query large amounts of data on\nthe local device, consider using a database instead of a local file or\nkey-value store. In general, databases provide faster inserts, updates,\nand queries compared to other local persistence solutions.\n\nFlutter apps can make use of the SQLite databases via the\n[sqflite][] plugin available on pub.dev.\nThis recipe demonstrates the basics of using sqflite\nto insert, read, update, and remove data about various Dogs.\n\nIf you are new to SQLite and SQL statements, review the\n[SQLite Tutorial][] to learn the basics before\ncompleting this recipe.\n\nThis recipe uses the following steps:\nAdd the dependencies.\nDefine the Dog data model.\nOpen the database.\nCreate the dogs table.\nInsert a Dog into the database.\nRetrieve the list of dogs.\nUpdate a Dog in the database.\nDelete a Dog from the database.\nAdd the dependencies\n\nTo work with SQLite databases, import the sqflite and\npath packages.\n\n   The sqflite package provides classes and functions to\n    interact with a SQLite database.\n   The path package provides functions to\n    define the location for storing the database on disk.\n\nTo add the packages as a dependency,\nrun flutter pub add:\n\nMake sure to import the packages in the file you'll be working in.\n\nDefine the Dog data model\n\nBefore creating the table to store information on Dogs, take a few moments to\ndefine the data that needs to be stored. For this example, define a Dog class\nthat contains three pieces of data:\nA unique id, the name, and the age of each dog.\n\nOpen the database\n\nBefore reading and writing data to the database, open a connection\nto the database. This involves two steps:\nDefine the path to the database file using getDatabasesPath() from the\n  sqflite package, combined with the join function from the path package.\nOpen the database with the openDatabase() function from sqflite.\n\n:::note\nIn order to use the keyword await, the code must be placed\ninside an async function. You should place all the following\ntable functions inside void main() async {}.\n:::\n\nCreate the dogs table\n\nNext, create a table to store information about various Dogs.\nFor this example, create a table called dogs that defines the data\nthat can be stored. Each Dog contains an id, name, and age.\nTherefore, these are represented as three columns in the dogs table.\nThe id is a Dart int, and is stored as an INTEGER SQLite\n     Datatype. It is also good practice to use an id as the primary\n     key for the table to improve query and update times.\nThe name is a Dart String, and is stored as a TEXT SQLite\n     Datatype.\nThe age is also a Dart int, and is stored as an INTEGER\n     Datatype.\n\nFor more information about the available Datatypes that can be stored in a\nSQLite database, see the [official SQLite Datatypes documentation][].\n\nInsert a Dog into the database\n\nNow that you have a database with a table suitable for storing information\nabout various dogs, it's time to read and write data.\n\nFirst, insert a Dog into the dogs table. This involves two steps:\nConvert the Dog into a Map\nUse the [insert()][] method to store the\n   Map in the dogs table.\n\nRetrieve the list of Dogs\n\nNow that a Dog is stored in the database, query the database\nfor a specific dog or a list of all dogs. This involves two steps:\nRun a query against the dogs table. This returns a List.\nConvert the List into a List.\n\nUpdate a Dog in the database\n\nAfter inserting information into the database,\nyou might want to update that information at a later time.\nYou can do this by using the [update()][]\nmethod from the sqflite library.\n\nThis involves two steps:\nConvert the Dog into a Map.\nUse a where clause to ensure you update the correct Dog.\n\n:::warning\nAlways use whereArgs to pass arguments to a where statement.\nThis helps safeguard against SQL injection attacks.\n\nDo not use string interpolation, such as where: \"id = \${dog.id}\"!\n:::\nDelete a Dog from the database\n\nIn addition to inserting and updating information about Dogs,\nyou can also remove dogs from the database. To delete data,\nuse the [delete()][] method from the sqflite library.\n\nIn this section, create a function that takes an id and deletes the dog with\na matching id from the database. To make this work, you must provide a where\nclause to limit the records being deleted.\n\nExample\n\nTo run the example:\nCreate a new Flutter project.\nAdd the sqflite and path packages to your pubspec.yaml.\nPaste the following code into a new file called lib/db_test.dart.\nRun the code with flutter run lib/db_test.dart.\n\nUse relationships between tables\n\n:::note\nThis is a more advanced use case and not required for basic usage.\n:::\n\nIn real-world applications, you often need to model relationships between tables.\n\nFor example, instead of storing all data in a single table, you can separate\nrelated data into multiple tables and connect them using foreign keys.\n\nIn this example, each dog is associated with a breed using the breed_id field.\nThis allows you to organize data more efficiently and avoid duplication.",
        codeSnippet: "\$ flutter pub add sqflite path\n\nimport 'dart:async';\n\nimport 'package:flutter/widgets.dart';\nimport 'package:path/path.dart';\nimport 'package:sqflite/sqflite.dart';\n\nclass Dog {\n  final int id;\n  final String name;\n  final int age;\n\n  const Dog({required this.id, required this.name, required this.age});\n}\n\n// Avoid errors caused by flutter upgrade.\n// Importing 'package:flutter/widgets.dart' is required.\nWidgetsFlutterBinding.ensureInitialized();\n// Open the database and store the reference.\nfinal database = openDatabase(\n  // Set the path to the database. Note: Using the `join` function from the\n  // `path` package is best practice to ensure the path is correctly\n  // constructed for each platform.\n  join(await getDatabasesPath(), 'doggie_database.db'),\n);\n\nfinal database = openDatabase(\n  // Set the path to the database. Note: Using the `join` function from the\n  // `path` package is best practice to ensure the path is correctly\n  // constructed for each platform.\n  join(await getDatabasesPath(), 'doggie_database.db'),\n  // When the database is first created, create a table to store dogs.\n  onCreate: (db, version) {\n    // Run the CREATE TABLE statement on the database.\n    return db.execute(\n      'CREATE TABLE dogs(id INTEGER PRIMARY KEY, name TEXT, age INTEGER)',\n    );\n  },\n  // Set the version. This executes the onCreate function and provides a\n  // path to perform database upgrades and downgrades.\n  version: 1,\n);\n\nclass Dog {\n  final int id;\n  final String name;\n  final int age;\n\n  Dog({required this.id, required this.name, required this.age});\n\n  // Convert a Dog into a Map. The keys must correspond to the names of the\n  // columns in the database.\n  Map<String, Object?> toMap() {\n    return {'id': id, 'name': name, 'age': age};\n  }\n\n  // Implement toString to make it easier to see information about\n  // each dog when using the print statement.\n  @override\n  String toString() {\n    return 'Dog{id: \$id, name: \$name, age: \$age}';\n  }\n}\n\n// Define a function that inserts dogs into the database\nFuture<void> insertDog(Dog dog) async {\n  // Get a reference to the database.\n  final db = await database;\n\n  // Insert the Dog into the correct table. You might also specify the\n  // `conflictAlgorithm` to use in case the same dog is inserted twice.\n  //\n  // In this case, replace any previous data.\n  await db.insert(\n    'dogs',\n    dog.toMap(),\n    conflictAlgorithm: ConflictAlgorithm.replace,\n  );\n}\n\n// Create a Dog and add it to the dogs table\nvar fido = Dog(id: 0, name: 'Fido', age: 35);\n\nawait insertDog(fido);\n\n// A method that retrieves all the dogs from the dogs table.\nFuture<List<Dog>> dogs() async {\n  // Get a reference to the database.\n  final db = await database;\n\n  // Query the table for all the dogs.\n  final List<Map<String, Object?>> dogMaps = await db.query('dogs');\n\n  // Convert the list of each dog's fields into a list of `Dog` objects.\n  return [\n    for (final {'id': id as int, 'name': name as String, 'age': age as int}\n        in dogMaps)\n      Dog(id: id, name: name, age: age),\n  ];\n}\n\n// Now, use the method above to retrieve all the dogs.\nprint(await dogs()); // Prints a list that include Fido.\n\nFuture<void> updateDog(Dog dog) async {\n  // Get a reference to the database.\n  final db = await database;\n\n  // Update the given Dog.\n  await db.update(\n    'dogs',\n    dog.toMap(),\n    // Ensure that the Dog has a matching id.\n    where: 'id = ?',\n    // Pass the Dog's id as a whereArg to prevent SQL injection.\n    whereArgs: [dog.id],\n  );\n}\n\n// Update Fido's age and save it to the database.\nfido = Dog(id: fido.id, name: fido.name, age: fido.age + 7);\nawait updateDog(fido);\n\n// Print the updated results.\nprint(await dogs()); // Prints Fido with age 42.\n\nFuture<void> deleteDog(int id) async {\n  // Get a reference to the database.\n  final db = await database;\n\n  // Remove the Dog from the database.\n  await db.delete(\n    'dogs',\n    // Use a `where` clause to delete a specific dog.\n    where: 'id = ?',\n    // Pass the Dog's id as a whereArg to prevent SQL injection.\n    whereArgs: [id],\n  );\n}\n\nimport 'dart:async';\n\nimport 'package:flutter/widgets.dart';\nimport 'package:path/path.dart';\nimport 'package:sqflite/sqflite.dart';\n\nvoid main() async {\n  // Avoid errors caused by flutter upgrade.\n  // Importing 'package:flutter/widgets.dart' is required.\n  WidgetsFlutterBinding.ensureInitialized();\n  // Open the database and store the reference.\n  final database = openDatabase(\n    // Set the path to the database. Note: Using the `join` function from the\n    // `path` package is best practice to ensure the path is correctly\n    // constructed for each platform.\n    join(await getDatabasesPath(), 'doggie_database.db'),\n    // When the database is first created, create a table to store dogs.\n    onCreate: (db, version) {\n      // Run the CREATE TABLE statement on the database.\n      return db.execute(\n        'CREATE TABLE dogs(id INTEGER PRIMARY KEY, name TEXT, age INTEGER)',\n      );\n    },\n    // Set the version. This executes the onCreate function and provides a\n    // path to perform database upgrades and downgrades.\n    version: 1,\n  );\n\n  // Define a function that inserts dogs into the database\n  Future<void> insertDog(Dog dog) async {\n    // Get a reference to the database.\n    final db = await database;\n\n    // Insert the Dog into the correct table. You might also specify the\n    // `conflictAlgorithm` to use in case the same dog is inserted twice.\n    //\n    // In this case, replace any previous data.\n    await db.insert(\n      'dogs',\n      dog.toMap(),\n      conflictAlgorithm: ConflictAlgorithm.replace,\n    );\n  }\n\n  // A method that retrieves all the dogs from the dogs table.\n  Future<List<Dog>> dogs() async {\n    // Get a reference to the database.\n    final db = await database;\n\n    // Query the table for all the dogs.\n    final List<Map<String, Object?>> dogMaps = await db.query('dogs');\n\n    // Convert the list of each dog's fields into a list of `Dog` objects.\n    return [\n      for (final {'id': id as int, 'name': name as String, 'age': age as int}\n          in dogMaps)\n        Dog(id: id, name: name, age: age),\n    ];\n  }\n\n  Future<void> updateDog(Dog dog) async {\n    // Get a reference to the database.\n    final db = await database;\n\n    // Update the given Dog.\n    await db.update(\n      'dogs',\n      dog.toMap(),\n      // Ensure that the Dog has a matching id.\n      where: 'id = ?',\n      // Pass the Dog's id as a whereArg to prevent SQL injection.\n      whereArgs: [dog.id],\n    );\n  }\n\n  Future<void> deleteDog(int id) async {\n    // Get a reference to the database.\n    final db = await database;\n\n    // Remove the Dog from the database.\n    await db.delete(\n      'dogs',\n      // Use a `where` clause to delete a specific dog.\n      where: 'id = ?',\n      // Pass the Dog's id as a whereArg to prevent SQL injection.\n      whereArgs: [id],\n    );\n  }\n\n  // Create a Dog and add it to the dogs table\n  var fido = Dog(id: 0, name: 'Fido', age: 35);\n\n  await insertDog(fido);\n\n  // Now, use the method above to retrieve all the dogs.\n  print(await dogs()); // Prints a list that include Fido.\n\n  // Update Fido's age and save it to the database.\n  fido = Dog(id: fido.id, name: fido.name, age: fido.age + 7);\n  await updateDog(fido);\n\n  // Print the updated results.\n  print(await dogs()); // Prints Fido with age 42.\n\n  // Delete Fido from the database.\n  await deleteDog(fido.id);\n\n  // Print the list of dogs (empty).\n  print(await dogs());\n}\n\nclass Dog {\n  final int id;\n  final String name;\n  final int age;\n\n  Dog({required this.id, required this.name, required this.age});\n\n  // Convert a Dog into a Map. The keys must correspond to the names of the\n  // columns in the database.\n  Map<String, Object?> toMap() {\n    return {'id': id, 'name': name, 'age': age};\n  }\n\n  // Implement toString to make it easier to see information about\n  // each dog when using the print statement.\n  @override\n  String toString() {\n    return 'Dog{id: \$id, name: \$name, age: \$age}';\n  }\n}\n\nCREATE TABLE breeds(\n  id INTEGER PRIMARY KEY,\n  name TEXT\n);\n\nYou can execute these statements using the `db.execute()` method from the `sqflite` package.\n\nCREATE TABLE dogs(\n  id INTEGER PRIMARY KEY,\n  name TEXT,\n  age INTEGER,\n  breed_id INTEGER,\n  FOREIGN KEY (breed_id) REFERENCES breeds(id)\n);",
        hasImage: false,
      ),
      AppLesson(
        title: "Google Mobile Ads",
        body: "title: Add ads to your mobile Flutter app or game\nshortTitle: Show ads\ndescription: How to use the google_mobile_ads package to show ads in Flutter.\n\n{% comment %}\n  This partly duplicates the AdMob documentation\n  here: https://developers.google.com/admob/flutter/quick-start\n\n  The added value of this page is that it's more straightforward for\n  someone who just has a Flutter app or game and wants to add\n  monetization to it.\n\n  In short, this is a friendlier --- though not as comprehensive ---\n  introduction to ads in Flutter.\n{% endcomment %}\n\nMany developers use advertising to monetize their mobile apps and games.\nThis allows their app to be downloaded free of charge,\nwhich improves the app's popularity.\n\n{:.site-illustration}\n\nTo add ads to your Flutter project, use\nAdMob,\nGoogle's mobile advertising platform.\nThis recipe demonstrates how to use the\ngoogle_mobile_ads\npackage to add a banner ad to your app or game.\n\n:::note\nApart from AdMob, the google_mobile_ads package also supports\nAd Manager, a platform intended for large publishers. Integrating Ad\nManager resembles integrating AdMob, but it won't be covered in this\ncookbook recipe. To use Ad Manager, follow the\nAd Manager documentation.\n:::\nGet AdMob App IDs\nGo to AdMob and set up an\n    account. This could take some time because you need to provide\n    banking information, sign contracts, and so on.\nWith the AdMob account ready, create two Apps in AdMob: one for\n    Android and one for iOS.\nOpen the App settings section.\nGet the AdMob App IDs for both the Android app and the iOS app.\n    They resemble ca-app-pub-1234567890123456~1234567890. Note the\n    tilde (~) between the two numbers.\n    {% comment %} https://support.google.com/admob/answer/7356431 for future reference {% endcomment %}\nPlatform-specific setup\n\nUpdate your Android and iOS configurations to include your App IDs.\n\n{% comment %}\n    Content below is more or less a copypaste from devsite:\n    https://developers.google.com/admob/flutter/quick-start#platform_specific_setup\n{% endcomment %}\nAndroid\n\nAdd your AdMob app ID to your Android app.\nOpen the app's android/app/src/main/AndroidManifest.xml file.\nAdd a new  tag.\nSet the android:name element with a value of\n    com.google.android.gms.ads.APPLICATION_ID.\nSet the android:value element with the value to your own AdMob app\n    ID that you got in the previous step.\n    Include them in quotes as shown:\n\n\niOS\n\nAdd your AdMob app ID to your iOS app.\nOpen your app's ios/Runner/Info.plist file.\nEnclose GADApplicationIdentifier with a key tag.\nEnclose your AdMob app ID with a string tag. You created this AdMob\n    App ID in step 1.\nAdd the google_mobile_ads plugin\n\nTo add the google_mobile_ads plugin as a dependency, run\nflutter pub add:\n\n:::note\nOnce you add the plugin, your Android app might fail to build with a\nDexArchiveMergerException:\n\nTo resolve this, execute the flutter run command in the terminal, not\nthrough an IDE plugin. The flutter tool can detect the issue and ask\nwhether it should try to solve it. Answer y, and the problem goes away.\nYou can return to running your app from an IDE after that.\n\n:::\nInitialize the Mobile Ads SDK\n\nYou need to initialize the Mobile Ads SDK before loading ads.\nCall MobileAds.instance.initialize() to initialize the Mobile Ads\n    SDK.\n\n\n\n\nRun the initialization step at startup, as shown above,\nso that the AdMob SDK has enough time to initialize before it is needed.\n\n:::note\nMobileAds.instance.initialize() returns a Future but, the\nway the SDK is built, you don't need to await it.\nIf you try to load an ad before that Future is completed,\nthe SDK will gracefully wait until the initialization, and then load the ad.\nYou can await the Future\nif you want to know the exact time when the AdMob SDK is ready.\n:::\nLoad a banner ad\n\nTo show an ad, you need to request it from AdMob.\n\nTo load a banner ad, construct a BannerAd instance, and\ncall load() on it.\n\n:::note\nThe following code snippet refers to fields such a adSize, adUnitId\nand bannerAd. This will all make more sense in a later step.\n:::\n\nTo view a complete example, check out the last step of this recipe.\nShow banner ad\n\nOnce you have a loaded instance of BannerAd, use AdWidget to show it.\n\nIt's a good idea to wrap the widget in a SafeArea (so that no part of\nthe ad is obstructed by device notches) and a SizedBox (so that it has\nits specified, constant size before and after loading).\n\nYou must dispose of an ad when you no longer need to access it. The best\npractice for when to call dispose() is either after the AdWidget is\nremoved from the widget tree or in the\nBannerAdListener.onAdFailedToLoad() callback.\n\nConfigure ads\n\nTo show anything beyond test ads, you have to register ad units.\nOpen AdMob.\nCreate an *Ad unit* for each of the AdMob apps.\n\n\n\n    This asks for the Ad unit's format. AdMob provides many formats\n    beyond banner ads --- interstitials, rewarded ads, app open ads, and\n    so on.\n    The API for those is similar, and documented in the\n    AdMob documentation\n    and through\n    official samples.\nChoose banner ads.\nGet the *Ad unit IDs* for both the Android app and the iOS app.\n    You can find these in the Ad units section. They look something\n    like ca-app-pub-1234567890123456/1234567890. The format resembles\n    the *App ID* but with a slash (/) between the two numbers. This\n    distinguishes an *Ad unit ID* from an *App ID*.\nAdd these *Ad unit IDs* to the constructor of BannerAd,\n    depending on the target app platform.\n\n\nFinal touches\n\nTo display the ads in a published app or game (as opposed to debug or\ntesting scenarios), your app must meet additional requirements:\nYour app must be reviewed and approved before it can fully serve\n    ads.\n    Follow AdMob's app readiness guidelines.\n    For example, your app must be listed on at least one of the\n    supported stores such as Google Play Store or Apple App Store.\nYou must create an app-ads.txt\n    file and publish it on your developer website.\n\n{:.site-illustration}\n\nTo learn more about app and game monetization,\nvisit the official sites\nof AdMob\nand Ad Manager.\nComplete example\n\nThe following code implements a simple stateful widget that loads a\nbanner ad and shows it.\n\n:::tip\nIn many cases, you will want to load the ad _outside a widget.\n\nFor example, you can load it in a ChangeNotifier, a BLoC, a controller,\nor whatever else you are using for app-level state. This way, you can\npreload a banner ad in advance, and have it ready to show for when the\nuser navigates to a new screen.\n\nVerify that you have loaded the BannerAd instance before showing it with\nan AdWidget, and that you dispose of the instance when it is no longer\nneeded.\n:::",
        codeSnippet: "<manifest>\n        <application>\n            ...\n\n            <!-- Sample AdMob app ID: ca-app-pub-3940256099942544~3347511713 -->\n            <meta-data\n                android:name=\"com.google.android.gms.ads.APPLICATION_ID\"\n                android:value=\"ca-app-pub-xxxxxxxxxxxxxxxx~yyyyyyyyyy\"/>\n        </application>\n    </manifest>\n    \n\n    <key>GADApplicationIdentifier</key>\n    <string>ca-app-pub-################~##########</string>\n    \n\n\$ flutter pub add google_mobile_ads\n\nError while merging dex archives:\nThe number of method references in a .dex file cannot exceed 64K.\n\n    void main() async {\n      WidgetsFlutterBinding.ensureInitialized();\n      unawaited(MobileAds.instance.initialize());\n    \n      runApp(const MyApp());\n    }\n    \n\n/// Loads a banner ad.\nvoid _loadAd() {\n  final bannerAd = BannerAd(\n    size: widget.adSize,\n    adUnitId: widget.adUnitId,\n    request: const AdRequest(),\n    listener: BannerAdListener(\n      // Called when an ad is successfully received.\n      onAdLoaded: (ad) {\n        if (!mounted) {\n          ad.dispose();\n          return;\n        }\n        setState(() {\n          _bannerAd = ad as BannerAd;\n        });\n      },\n      // Called when an ad request failed.\n      onAdFailedToLoad: (ad, error) {\n        debugPrint('BannerAd failed to load: \$error');\n        ad.dispose();\n      },\n    ),\n  );\n\n  // Start loading.\n  bannerAd.load();\n}\n\nAdWidget(ad: _bannerAd)\n\n@override\nWidget build(BuildContext context) {\n  return SafeArea(\n    child: SizedBox(\n      width: widget.adSize.width.toDouble(),\n      height: widget.adSize.height.toDouble(),\n      child: _bannerAd == null\n          // Nothing to render yet.\n          ? const SizedBox()\n          // The actual ad.\n          : AdWidget(ad: _bannerAd!),\n    ),\n  );\n}\n\n_bannerAd?.dispose();\n\n    final String adUnitId = Platform.isAndroid\n        // Use this ad unit on Android...\n        ? 'ca-app-pub-3940256099942544/6300978111'\n        // ... or this one on iOS.\n        : 'ca-app-pub-3940256099942544/2934735716';\n    \n\nimport 'dart:io';\n\nimport 'package:flutter/widgets.dart';\nimport 'package:google_mobile_ads/google_mobile_ads.dart';\n\nclass MyBannerAdWidget extends StatefulWidget {\n  /// The requested size of the banner. Defaults to [AdSize.banner].\n  final AdSize adSize;\n\n  /// The AdMob ad unit to show.\n  ///\n  /// TODO: replace this test ad unit with your own ad unit\n  final String adUnitId = Platform.isAndroid\n      // Use this ad unit on Android...\n      ? 'ca-app-pub-3940256099942544/6300978111'\n      // ... or this one on iOS.\n      : 'ca-app-pub-3940256099942544/2934735716';\n\n  MyBannerAdWidget({super.key, this.adSize = AdSize.banner});\n\n  @override\n  State<MyBannerAdWidget> createState() => _MyBannerAdWidgetState();\n}\n\nclass _MyBannerAdWidgetState extends State<MyBannerAdWidget> {\n  /// The banner ad to show. This is `null` until the ad is actually loaded.\n  BannerAd? _bannerAd;\n\n  @override\n  Widget build(BuildContext context) {\n    return SafeArea(\n      child: SizedBox(\n        width: widget.adSize.width.toDouble(),\n        height: widget.adSize.height.toDouble(),\n        child: _bannerAd == null\n            // Nothing to render yet.\n            ? const SizedBox()\n            // The actual ad.\n            : AdWidget(ad: _bannerAd!),\n      ),\n    );\n  }\n\n  @override\n  void initState() {\n    super.initState();\n    _loadAd();\n  }\n\n  @override\n  void dispose() {\n    _bannerAd?.dispose();\n    super.dispose();\n  }\n\n  /// Loads a banner ad.\n  void _loadAd() {\n    final bannerAd = BannerAd(\n      size: widget.adSize,\n      adUnitId: widget.adUnitId,\n      request: const AdRequest(),\n      listener: BannerAdListener(\n        // Called when an ad is successfully received.\n        onAdLoaded: (ad) {\n          if (!mounted) {\n            ad.dispose();\n            return;\n          }\n          setState(() {\n            _bannerAd = ad as BannerAd;\n          });\n        },\n        // Called when an ad request failed.\n        onAdFailedToLoad: (ad, error) {\n          debugPrint('BannerAd failed to load: \$error');\n          ad.dispose();\n        },\n      ),\n    );\n\n    // Start loading.\n    bannerAd.load();\n  }\n}",
        hasImage: true,
      ),
      AppLesson(
        title: "Index",
        body: "title: Flutter plugin cookbook\nshortTitle: Plugins\ndescription: A catalog of recipes showcasing using plugins in your Flutter app.\nlayout: toc",
        codeSnippet: "",
        hasImage: false,
      ),
      AppLesson(
        title: "Picture Using Camera",
        body: "title: Take a picture using the camera\ndescription: How to use a camera plugin on mobile.\n\nMany apps require working with the device's cameras to\ntake photos and videos.  Flutter provides the [camera][] plugin\nfor this purpose. The camera plugin provides tools to get a list of the\navailable cameras, display a preview coming from a specific camera,\nand take photos or videos.\n\n:::note\nThe [camera_android_camerax][] plugin,\nbuilt on top of the [CameraX][] Android library,\nimproves image resolution with automatic selection\nof the resolution based on the device's capability.\nThis plugin also helps deal with device quirks,\ndefined as camera hardware that might\nnot work as expected.\n\nFor more information,\ncheck out the Google I/O 2024 talk,\n[Building picture perfect camera experiences in Flutter with CameraX][camerax-video].\n:::\n\nThis recipe demonstrates how to use the camera plugin to display a preview,\ntake a photo, and display it using the following steps:\nAdd the required dependencies.\nGet a list of the available cameras.\nCreate and initialize the CameraController.\nUse a CameraPreview to display the camera's feed.\nTake a picture with the CameraController.\nDisplay the picture with an Image widget.\nAdd the required dependencies\n\nTo complete this recipe, you need to add three dependencies to your app:\n\n[camera][]\n: Provides tools to work with the cameras on the device.\n\n[path_provider][]\n: Finds the correct paths to store images.\n\n[path][]\n: Creates paths that work on any platform.\n\nTo add the packages as dependencies, run flutter pub add:\n\n:::tip\nFor android, You must update minSdkVersion to 21 (or higher).\nOn iOS, the following lines must be added inside\n  ios/Runner/Info.plist to the access the camera and microphone.\n\n\n:::\nGet a list of the available cameras\n\nNext, get a list of available cameras using the camera plugin.\n\nCreate and initialize the CameraController\n\nOnce you have a camera, use the following steps to\ncreate and initialize a CameraController.\nThis process establishes a connection to\nthe device's camera that allows you to control the camera\nand display a preview of the camera's feed.\nCreate a StatefulWidget with a companion State class.\nAdd a variable to the State class to store the CameraController.\nAdd a variable to the State class to store the Future\n     returned from CameraController.initialize().\nCreate and initialize the controller in the initState() method.\nDispose of the controller in the dispose() method.\n\n:::warning\nIf you don't initialize the CameraController,\nyou cannot use the camera to display a preview and take pictures.\n:::\nUse a CameraPreview to display the camera's feed\n\nNext, use the CameraPreview widget from the camera package to\ndisplay a preview of the camera's feed.\n\n:::note Remember\nYou must wait until the controller has finished\ninitializing before working with the camera. Therefore,\nyou must wait for the _initializeControllerFuture(), created\nin the previous step, to complete before showing a CameraPreview.\n:::\n\nUse a [FutureBuilder][] for exactly this purpose.\n\nTake a picture with the CameraController\n\nYou can use the CameraController to take pictures using the\n[takePicture()][] method, which returns an [XFile][],\na cross-platform, simplified File abstraction.\nOn both Android and IOS, the new image is stored in their\nrespective cache directories,\nand the path to that location is returned in the XFile.\n\nIn this example, create a FloatingActionButton that takes a picture\nusing the CameraController when a user taps on the button.\n\nTaking a picture requires 2 steps:\nEnsure that the camera is initialized.\nUse the controller to take a picture and ensure\n     that it returns a Future.\n\nIt is good practice to wrap these operations in a try / catch block in order\nto handle any errors that might occur.\n\nDisplay the picture with an Image widget\n\nIf you take the picture successfully, you can then display the saved picture\nusing an Image widget. In this case, the picture is stored as a file on\nthe device.\n\nTherefore, you must provide a File to the Image.file constructor.\nYou can create an instance of the File class by passing the path created in\nthe previous step.\n\nComplete example",
        codeSnippet: "\$ flutter pub add camera path_provider path\n\n  <key>NSCameraUsageDescription</key>\n  <string>Explanation on why the camera access is needed.</string>\n  <key>NSMicrophoneUsageDescription</key>\n  <string>Explanation on why the microphone access is needed.</string>\n  \n\n// Ensure that plugin services are initialized so that `availableCameras()`\n// can be called before `runApp()`\nWidgetsFlutterBinding.ensureInitialized();\n\n// Obtain a list of the available cameras on the device.\nfinal cameras = await availableCameras();\n\n// Get a specific camera from the list of available cameras.\nfinal firstCamera = cameras.first;\n\n// A screen that allows users to take a picture using a given camera.\nclass TakePictureScreen extends StatefulWidget {\n  const TakePictureScreen({super.key, required this.camera});\n\n  final CameraDescription camera;\n\n  @override\n  TakePictureScreenState createState() => TakePictureScreenState();\n}\n\nclass TakePictureScreenState extends State<TakePictureScreen> {\n  late CameraController _controller;\n  late Future<void> _initializeControllerFuture;\n\n  @override\n  void initState() {\n    super.initState();\n    // To display the current output from the Camera,\n    // create a CameraController.\n    _controller = CameraController(\n      // Get a specific camera from the list of available cameras.\n      widget.camera,\n      // Define the resolution to use.\n      ResolutionPreset.medium,\n    );\n\n    // Next, initialize the controller. This returns a Future.\n    _initializeControllerFuture = _controller.initialize();\n  }\n\n  @override\n  void dispose() {\n    // Dispose of the controller when the widget is disposed.\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // Fill this out in the next steps.\n    return Container();\n  }\n}\n\n// You must wait until the controller is initialized before displaying the\n// camera preview. Use a FutureBuilder to display a loading spinner until the\n// controller has finished initializing.\nFutureBuilder<void>(\n  future: _initializeControllerFuture,\n  builder: (context, snapshot) {\n    if (snapshot.connectionState == ConnectionState.done) {\n      // If the Future is complete, display the preview.\n      return CameraPreview(_controller);\n    } else {\n      // Otherwise, display a loading indicator.\n      return const Center(child: CircularProgressIndicator());\n    }\n  },\n)\n\nFloatingActionButton(\n  // Provide an onPressed callback.\n  onPressed: () async {\n    // Take the Picture in a try / catch block. If anything goes wrong,\n    // catch the error.\n    try {\n      // Ensure that the camera is initialized.\n      await _initializeControllerFuture;\n\n      // Attempt to take a picture and then get the location\n      // where the image file is saved.\n      final image = await _controller.takePicture();\n    } catch (e) {\n      // If an error occurs, log the error to the console.\n      print(e);\n    }\n  },\n  child: const Icon(Icons.camera_alt),\n)\n\nImage.file(File('path/to/my/picture.png'));\n\nimport 'dart:async';\nimport 'dart:io';\n\nimport 'package:camera/camera.dart';\nimport 'package:flutter/material.dart';\n\nFuture<void> main() async {\n  // Ensure that plugin services are initialized so that `availableCameras()`\n  // can be called before `runApp()`\n  WidgetsFlutterBinding.ensureInitialized();\n\n  // Obtain a list of the available cameras on the device.\n  final cameras = await availableCameras();\n\n  // Get a specific camera from the list of available cameras.\n  final firstCamera = cameras.first;\n\n  runApp(\n    MaterialApp(\n      theme: ThemeData.dark(),\n      home: TakePictureScreen(\n        // Pass the appropriate camera to the TakePictureScreen widget.\n        camera: firstCamera,\n      ),\n    ),\n  );\n}\n\n// A screen that allows users to take a picture using a given camera.\nclass TakePictureScreen extends StatefulWidget {\n  const TakePictureScreen({super.key, required this.camera});\n\n  final CameraDescription camera;\n\n  @override\n  TakePictureScreenState createState() => TakePictureScreenState();\n}\n\nclass TakePictureScreenState extends State<TakePictureScreen> {\n  late CameraController _controller;\n  late Future<void> _initializeControllerFuture;\n\n  @override\n  void initState() {\n    super.initState();\n    // To display the current output from the Camera,\n    // create a CameraController.\n    _controller = CameraController(\n      // Get a specific camera from the list of available cameras.\n      widget.camera,\n      // Define the resolution to use.\n      ResolutionPreset.medium,\n    );\n\n    // Next, initialize the controller. This returns a Future.\n    _initializeControllerFuture = _controller.initialize();\n  }\n\n  @override\n  void dispose() {\n    // Dispose of the controller when the widget is disposed.\n    _controller.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Take a picture')),\n      // You must wait until the controller is initialized before displaying the\n      // camera preview. Use a FutureBuilder to display a loading spinner until the\n      // controller has finished initializing.\n      body: FutureBuilder<void>(\n        future: _initializeControllerFuture,\n        builder: (context, snapshot) {\n          if (snapshot.connectionState == ConnectionState.done) {\n            // If the Future is complete, display the preview.\n            return CameraPreview(_controller);\n          } else {\n            // Otherwise, display a loading indicator.\n            return const Center(child: CircularProgressIndicator());\n          }\n        },\n      ),\n      floatingActionButton: FloatingActionButton(\n        // Provide an onPressed callback.\n        onPressed: () async {\n          // Take the Picture in a try / catch block. If anything goes wrong,\n          // catch the error.\n          try {\n            // Ensure that the camera is initialized.\n            await _initializeControllerFuture;\n\n            // Attempt to take a picture and get the file `image`\n            // where it was saved.\n            final image = await _controller.takePicture();\n\n            if (!context.mounted) return;\n\n            // If the picture was taken, display it on a new screen.\n            await Navigator.of(context).push(\n              MaterialPageRoute<void>(\n                builder: (context) => DisplayPictureScreen(\n                  // Pass the automatically generated path to\n                  // the DisplayPictureScreen widget.\n                  imagePath: image.path,\n                ),\n              ),\n            );\n          } catch (e) {\n            // If an error occurs, log the error to the console.\n            print(e);\n          }\n        },\n        child: const Icon(Icons.camera_alt),\n      ),\n    );\n  }\n}\n\n// A widget that displays the picture taken by the user.\nclass DisplayPictureScreen extends StatelessWidget {\n  final String imagePath;\n\n  const DisplayPictureScreen({super.key, required this.imagePath});\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Display the Picture')),\n      // The image is stored as a file on the device. Use the `Image.file`\n      // constructor with the given path to display the image.\n      body: Image.file(File(imagePath)),\n    );\n  }\n}",
        hasImage: false,
      ),
      AppLesson(
        title: "Play Video",
        body: "title: Play and pause a video\ndescription: How to use the video_player plugin.\n\nPlaying videos is a common task in app development,\nand Flutter apps are no exception. To play videos,\nthe Flutter team provides the [video_player][] plugin.\nYou can use the video_player plugin to play videos\nstored on the file system, as an asset, or from the internet.\n\n:::warning\nAt this time,\nthe video_player plugin doesn't work on Linux and Windows.\nTo learn more, check out the [video_player][] package.\n:::\n\nOn iOS, the video_player plugin makes use of\n[AVPlayer][] to handle playback. On Android,\nit uses [ExoPlayer][].\n\nThis recipe demonstrates how to use the video_player package to stream a\nvideo from the internet with basic play and pause controls using\nthe following steps:\nAdd the video_player dependency.\nAdd permissions to your app.\nCreate and initialize a VideoPlayerController.\nDisplay the video player.\nPlay and pause the video.\nAdd the video_player dependency\n\nThis recipe depends on one Flutter plugin: video_player.\nFirst, add this dependency to your project.\n\nTo add the video_player package as a dependency, run flutter pub add:\nAdd permissions to your app\n\nNext, update your android and ios configurations to ensure\nthat your app has the correct permissions to stream videos\nfrom the internet.\nAndroid\n\nAdd the following permission to the AndroidManifest.xml file just after the\n definition. The AndroidManifest.xml file is found at\n/android/app/src/main/AndroidManifest.xml.\niOS\n\nFor iOS, add the following to the Info.plist file found at\n/ios/Runner/Info.plist.\n\n:::warning\nThe video_player plugin can only play asset videos in iOS simulators.\nYou must test network-hosted videos on physical iOS devices.\n:::\nmacOS\n\nIf you use network-based videos,\n[add the com.apple.security.network.client entitlement][mac-entitlement].\nWeb\n\nFlutter web does not support dart:io,\nso avoid using the VideoPlayerController.file constructor for the plugin.\nUsing this constructor attempts to create aVideoPlayerController.file\nthat throws an UnimplementedError.\n\nDifferent web browsers might have different video-playback capabilities,\nsuch as supported formats or autoplay.\nCheck the [video_player_web] package for more web-specific information.\n\nThe VideoPlayerOptions.mixWithOthers option can't be implemented in web,\nat least at the moment. If you use this option in web it will be silently ignored.\nCreate and initialize a VideoPlayerController\n\nNow that you have the video_player plugin installed with the correct\npermissions, create a VideoPlayerController. The\nVideoPlayerController class allows you to connect to different types of\nvideos and control playback.\n\nBefore you can play videos, you must also initialize the controller.\nThis establishes the connection to the video and prepare the\ncontroller for playback.\n\nTo create and initialize the VideoPlayerController do the following:\nCreate a StatefulWidget with a companion State class\nAdd a variable to the State class to store the VideoPlayerController\nAdd a variable to the State class to store the Future returned from\n  VideoPlayerController.initialize\nCreate and initialize the controller in the initState method\nDispose of the controller in the dispose method\n\nDisplay the video player\n\nNow, display the video. The video_player plugin provides the\n[VideoPlayer][] widget to display the video initialized by\nthe VideoPlayerController.\nBy default, the VideoPlayer widget takes up as much space as possible.\nThis often isn't ideal for videos because they are meant\nto be displayed in a specific aspect ratio, such as 16x9 or 4x3.\n\nTherefore, wrap the VideoPlayer widget in an [AspectRatio][]\nwidget to ensure that the video has the correct proportions.\n\nFurthermore, you must display the VideoPlayer widget after the\n_initializeVideoPlayerFuture() completes. Use FutureBuilder to\ndisplay a loading spinner until the controller finishes initializing.\nNote: initializing the controller does not begin playback.\n\nPlay and pause the video\n\nBy default, the video starts in a paused state. To begin playback,\ncall the [play()][] method provided by the VideoPlayerController.\nTo pause playback, call the [pause()][] method.\n\nFor this example,\nadd a FloatingActionButton to your app that displays a play\nor pause icon depending on the situation.\nWhen the user taps the button,\nplay the video if it's currently paused,\nor pause the video if it's playing.\n\nComplete example\n\ndartpad title=\"Flutter video player hands-on example in DartPad\" run=\"true\"\nimport 'dart:async';\n\nimport 'package:flutter/material.dart';\nimport 'package:video_player/video_player.dart';\n\nvoid main() => runApp(const VideoPlayerApp());\n\nclass VideoPlayerApp extends StatelessWidget {\n  const VideoPlayerApp({super.key});\n\n  @override\n  Widget build(BuildContext context) {\n    return const MaterialApp(\n      title: 'Video Player Demo',\n      home: VideoPlayerScreen(),\n    );\n  }\n}\n\nclass VideoPlayerScreen extends StatefulWidget {\n  const VideoPlayerScreen({super.key});\n\n  @override\n  State createState() => _VideoPlayerScreenState();\n}\n\nclass _VideoPlayerScreenState extends State {\n  late VideoPlayerController _controller;\n  late Future _initializeVideoPlayerFuture;\n\n  @override\n  void initState() {\n    super.initState();\n\n    // Create and store the VideoPlayerController. The VideoPlayerController\n    // offers several different constructors to play videos from assets, files,\n    // or the internet.\n    _controller = VideoPlayerController.networkUrl(\n      Uri.parse(\n        'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4',\n      ),\n    );\n\n    // Initialize the controller and store the Future for later use.\n    _initializeVideoPlayerFuture = _controller.initialize();\n\n    // Use the controller to loop the video.\n    _controller.setLooping(true);\n  }\n\n  @override\n  void dispose() {\n    // Ensure disposing of the VideoPlayerController to free up resources.\n    _controller.dispose();\n\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    return Scaffold(\n      appBar: AppBar(title: const Text('Butterfly Video')),\n      // Use a FutureBuilder to display a loading spinner while waiting for the\n      // VideoPlayerController to finish initializing.\n      body: FutureBuilder(\n        future: _initializeVideoPlayerFuture,\n        builder: (context, snapshot) {\n          if (snapshot.connectionState == ConnectionState.done) {\n            // If the VideoPlayerController has finished initialization, use\n            // the data it provides to limit the aspect ratio of the video.\n            return AspectRatio(\n              aspectRatio: _controller.value.aspectRatio,\n              // Use the VideoPlayer widget to display the video.\n              child: VideoPlayer(_controller),\n            );\n          } else {\n            // If the VideoPlayerController is still initializing, show a\n            // loading spinner.\n            return const Center(child: CircularProgressIndicator());\n          }\n        },\n      ),\n      floatingActionButton: FloatingActionButton(\n        onPressed: () {\n          // Wrap the play or pause in a call to setState. This ensures the\n          // correct icon is shown.\n          setState(() {\n            // If the video is playing, pause it.\n            if (_controller.value.isPlaying) {\n              _controller.pause();\n            } else {\n              // If the video is paused, play it.\n              _controller.play();\n            }\n          });\n        },\n        // Display the correct icon depending on the state of the player.\n        child: Icon(\n          _controller.value.isPlaying ? Icons.pause : Icons.play_arrow,\n        ),\n      ),\n    );\n  }\n}",
        codeSnippet: "\$ flutter pub add video_player\n\n<manifest xmlns:android=\"http://schemas.android.com/apk/res/android\">\n    <application ...>\n\n    </application>\n\n    <uses-permission android:name=\"android.permission.INTERNET\"/>\n</manifest>\n\n<key>NSAppTransportSecurity</key>\n<dict>\n  <key>NSAllowsArbitraryLoads</key>\n  <true/>\n</dict>\n\nclass VideoPlayerScreen extends StatefulWidget {\n  const VideoPlayerScreen({super.key});\n\n  @override\n  State<VideoPlayerScreen> createState() => _VideoPlayerScreenState();\n}\n\nclass _VideoPlayerScreenState extends State<VideoPlayerScreen> {\n  late VideoPlayerController _controller;\n  late Future<void> _initializeVideoPlayerFuture;\n\n  @override\n  void initState() {\n    super.initState();\n\n    // Create and store the VideoPlayerController. The VideoPlayerController\n    // offers several different constructors to play videos from assets, files,\n    // or the internet.\n    _controller = VideoPlayerController.networkUrl(\n      Uri.parse(\n        'https://flutter.github.io/assets-for-api-docs/assets/videos/butterfly.mp4',\n      ),\n    );\n\n    _initializeVideoPlayerFuture = _controller.initialize();\n  }\n\n  @override\n  void dispose() {\n    // Ensure disposing of the VideoPlayerController to free up resources.\n    _controller.dispose();\n\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    // Complete the code in the next step.\n    return Container();\n  }\n}\n\n// Use a FutureBuilder to display a loading spinner while waiting for the\n// VideoPlayerController to finish initializing.\nFutureBuilder(\n  future: _initializeVideoPlayerFuture,\n  builder: (context, snapshot) {\n    if (snapshot.connectionState == ConnectionState.done) {\n      // If the VideoPlayerController has finished initialization, use\n      // the data it provides to limit the aspect ratio of the video.\n      return AspectRatio(\n        aspectRatio: _controller.value.aspectRatio,\n        // Use the VideoPlayer widget to display the video.\n        child: VideoPlayer(_controller),\n      );\n    } else {\n      // If the VideoPlayerController is still initializing, show a\n      // loading spinner.\n      return const Center(child: CircularProgressIndicator());\n    }\n  },\n)\n\nFloatingActionButton(\n  onPressed: () {\n    // Wrap the play or pause in a call to `setState`. This ensures the\n    // correct icon is shown.\n    setState(() {\n      // If the video is playing, pause it.\n      if (_controller.value.isPlaying) {\n        _controller.pause();\n      } else {\n        // If the video is paused, play it.\n        _controller.play();\n      }\n    });\n  },\n  // Display the correct icon depending on the state of the player.\n  child: Icon(\n    _controller.value.isPlaying ? Icons.pause : Icons.play_arrow,\n  ),\n)",
        hasImage: false,
      ),
